        const eased = t < 0.5 ? 2*t*t : 1 - Math.pow(-2*t + 2, 2) / 2;
        clipPlane.constant = startConstant + (endConstant - startConstant) * eased;
        if(typeof window._requestRender==='function') window._requestRender(200);
