            requestAnimationFrame(frame);
        } else {
            meshes.forEach(m=>{
                const mats = Array.isArray(m.material) ? m.material : [m.material];
                mats.forEach(mm=>{ if(mm){ mm.clippingPlanes = []; mm.needsUpdate = true; } });
            });
        }
    }
