    const slug = shape === 'Two-tier Round' ? 'two-tier' : shape === 'Three-tier Round' ? 'three-tier' : (SHAPE_SLUG[shape]||'round');
    if(slug === 'bundt' || shape === 'Number') return; // no rosettes for these
