        targetTier.updateMatrixWorld(true);
    });
    return true;
}

function fitRingOverlayTiersToBaseTiers(overlayGroup, baseTiers, diamMult, extraSinkFrac, perTierDiamMult){
    if(!overlayGroup || !baseTiers || baseTiers.length===0) return false;
    overlayGroup.position.set(0,0,0); overlayGroup.rotation.set(0,0,0); overlayGroup.scale.set(1,1,1);
    overlayGroup.updateMatrixWorld(true);
    let overlayTiers = getTierGroups(overlayGroup);

    // Some overlay exports (e.g. Sugar Icing for tiered Heart cakes) ship as
    // ONE combined ring mesh instead of one object per tier — unlike the base
    // cake and the Shell Border frosting file, which ARE split per tier. When
    // that happens, clone the single piece once per base tier so each tier
    // still gets its own independently scaled/positioned ring, instead of
    // silently falling back to a single flat fit for the whole cake (which is
    // why per-tier nudge values had no visible effect before this fix).
    if(overlayTiers.length === 1 && baseTiers.length > 1){
        const templateSrc = overlayTiers[0];
        const clones = [];
        for(let i=0;i<baseTiers.length;i++){
            const clone = i===0 ? templateSrc : templateSrc.clone(true);
            clone.traverse(node=>{
                if(node.isMesh){
                    node.geometry = node.geometry.clone();
                    if(Array.isArray(node.material)) node.material = node.material.map(m=>m.clone());
                    else if(node.material) node.material = node.material.clone();
                }
            });
            if(i>0) overlayGroup.add(clone);
            clones.push(clone);
        }
        overlayGroup.updateMatrixWorld(true);
        overlayTiers = clones;
    }

    if(overlayTiers.length===0 || overlayTiers.length!==baseTiers.length) return false;

    baseTiers.forEach((baseTier,i)=>{
        const ringTier = overlayTiers[i];
        const baseBox = new THREE.Box3().setFromObject(baseTier);
        const baseDiam = Math.max(baseBox.max.x-baseBox.min.x, baseBox.max.z-baseBox.min.z);

        ringTier.position.set(0,0,0); ringTier.rotation.set(0,0,0); ringTier.scale.set(1,1,1);
        ringTier.updateMatrixWorld(true);
        const rawBox = new THREE.Box3().setFromObject(ringTier);
        const rawDiam = Math.max(rawBox.max.x-rawBox.min.x, rawBox.max.z-rawBox.min.z);
        const tierDiamBoost = Array.isArray(perTierDiamMult) ? (perTierDiamMult[i] || 1.0) : 1.0;
        const scale = rawDiam>0.0001 ? (baseDiam*(diamMult||1.0)*tierDiamBoost)/rawDiam : 1.0;
        ringTier.scale.setScalar(scale);
        ringTier.updateMatrixWorld(true);

        const scaledBox = new THREE.Box3().setFromObject(ringTier);
        const scaledCenter = scaledBox.getCenter(new THREE.Vector3());
        const baseCenter = baseBox.getCenter(new THREE.Vector3());
        const sink = (scaledBox.max.y - scaledBox.min.y) * 0.12;
        // Extra downward push, as a fraction of THIS tier's own diameter — lets
        // Shell Border / Sugar Icing sit lower on the tier than the default 12%
        // sink alone allows, tuned independently per shape/overlay type/tier.
        // extraSinkFrac can be a single number (every tier) OR an array with one
        // value per tier (index 0 = bottom, matching baseTiers order) — needed
        // whenever different tiers require different vertical correction.
        const extraSinkForTier = Array.isArray(extraSinkFrac) ? (extraSinkFrac[i] || 0) : (extraSinkFrac || 0);
        const extraSink = baseDiam * extraSinkForTier;
        ringTier.position.set(
            baseCenter.x - scaledCenter.x,
            baseBox.max.y - scaledBox.min.y - sink - extraSink,
            baseCenter.z - scaledCenter.z
        );
        ringTier.updateMatrixWorld(true);
    });
    return true;
}
function alignDualDigits(gT,gU,wrapper){
    [gT,gU].forEach(g=>{g.position.set(0,0,0);g.rotation.set(0,0,0);g.scale.set(1,1,1);g.updateMatrixWorld(true);});

     const DUAL_DIGIT_TARGET_DIAM = inchesToWorldScale(4.5) * 0.85;
    function scaleDigitToDiam(g){
        const b = new THREE.Box3().setFromObject(g);
        const hSize = Math.max(b.max.x-b.min.x, b.max.z-b.min.z);
        const s = hSize > 0.0001 ? DUAL_DIGIT_TARGET_DIAM / hSize : 1.0;
        g.scale.set(s, s * NUMBER_CAKE_HEIGHT_MULT, s);
        g.updateMatrixWorld(true);
    }
    scaleDigitToDiam(gT);
    scaleDigitToDiam(gU);

    const bT=new THREE.Box3().setFromObject(gT), bU=new THREE.Box3().setFromObject(gU);
    const wT=bT.max.x-bT.min.x, wU=bU.max.x-bU.min.x;
    const gap=(wT+wU)*0.08, totalW=wT+gap+wU, startX=-totalW/2;
    gT.position.x=startX-bT.min.x; gU.position.x=startX+wT+gap-bU.min.x;
    gT.position.y=-bT.min.y; gU.position.y=-bU.min.y;
    gT.position.z=-(bT.min.z+(bT.max.z-bT.min.z)/2);
    gU.position.z=-(bU.min.z+(bU.max.z-bU.min.z)/2);
  wrapper.add(gT); wrapper.add(gU); wrapper.updateMatrixWorld(true);

    // Just center the wrapper at the origin and rest it on the floor —
    // NO further rescaling here, since each digit is already sized correctly.
    const wb = new THREE.Box3().setFromObject(wrapper);
    const wc = wb.getCenter(new THREE.Vector3());
    wrapper.position.set(-wc.x, -wb.min.y, -wc.z);
    wrapper.updateMatrixWorld(true);
    const wb2 = new THREE.Box3().setFromObject(wrapper);
    const midY2 = (wb2.min.y + wb2.max.y) * 0.5;
    wrapper.position.y -= midY2;
    wrapper.updateMatrixWorld(true);

    // Store the exact local placement used for the base digits so the icing digits
    // (loaded separately below) can reuse it instead of computing their own —
    // their bounding boxes can differ slightly from the base meshes, which was
    // pushing the icing out of alignment and making it appear to vanish.
    wrapper.userData.digitLocalPos = { T: gT.position.clone(), U: gU.position.clone() };
}
function clearScene(keepDecorations=false){
    invalidateCakeMeshesCache();
    while(sceneRoot.children.length){
        const _outgoing = sceneRoot.children[0];
        _disposeDecorGroup(_outgoing, false);
        sceneRoot.remove(_outgoing);
    }
   currentBase=currentFrost=currentDrip=currentIcing=currentTexture=currentRosette=currentCheesecakeCrust=null;
    if(!keepDecorations){
        fruitModels.forEach(m=>scene.remove(m.group));
        fruitModels.length=0;
        ferreroModels.forEach(m=>scene.remove(m.group));
        ferreroModels.length=0;
        kitkatModels.forEach(m=>scene.remove(m.group));
        kitkatModels.length=0;
        oreoModels.forEach(m=>scene.remove(m.group));
        oreoModels.length=0;
      if(typeof barShardModels!=='undefined'){
            barShardModels.forEach(m=>scene.remove(m.group));
            barShardModels.length=0;
        }
        if(typeof tobleroneModels!=='undefined'){
            tobleroneModels.forEach(m=>scene.remove(m.group));
            tobleroneModels.length=0;
        }
        candleModels.forEach(m=>{scene.remove(m.group);if(m.mixer){const mi=mixers.indexOf(m.mixer);if(mi>=0)mixers.splice(mi,1);}});
        candleModels.length=0;
    }
}
function addStandToScene(cakeGroup, extraSink=0){
    // Saved Drafts already has its own cake stand.
    // Do not create another stand inside the transparent preview.
    if (isPreview) return null;

    const TABLE_Y       = -1.18;
    const STAND_BOTTOM  =  0.255;
    const PLATE_TOP_LOCAL = 0.018;
    cakeGroup.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(cakeGroup);
    // Include fondant skin in radius calculation if present
    if(currentFrost && currentFrost !== cakeGroup) box.expandByObject(currentFrost);
    const cakeBottomY = box.min.y;
    const cakeRadius  = (box.max.x - box.min.x) * 0.5;
    const stand = buildCakePlateStand(cakeRadius);
    stand.userData.isStand = true;
    const standOriginY    = TABLE_Y + STAND_BOTTOM;
    const plateTopWorldY  = standOriginY + PLATE_TOP_LOCAL;
    const cx = (box.min.x + box.max.x) * 0.5;
    const cz = (box.min.z + box.max.z) * 0.5;
    stand.position.set(cx, standOriginY, cz);
    sceneRoot.add(stand);
    const lift = plateTopWorldY - cakeBottomY + 0.004 - extraSink;
    cakeGroup.position.y += lift;
    cakeGroup.updateMatrixWorld(true);
    return stand;
}

// ── Show a "no preview" placeholder when GLB fails to load ──
function showNoPreview(shapeName){
    clearScene(true);
    const geo = new THREE.BoxGeometry(0.01,0.01,0.01);
    const mat = new THREE.MeshBasicMaterial({visible:false});
    const dummy = new THREE.Mesh(geo,mat);
    sceneRoot.add(dummy);
    showStatus(`No preview — ${shapeName} GLB not found`);
    sceneRoot.visible=true;
    loadingEl.style.opacity='0';
    setTimeout(()=>{loadingEl.style.display='none';},400);
}

function updateCheesecakeCrust(cakeType){
    if(currentCheesecakeCrust){ _disposeDecorGroup(currentCheesecakeCrust, false); sceneRoot.remove(currentCheesecakeCrust); currentCheesecakeCrust=null; }
    if(cakeType !== 'Cheesecake') return;
    const cakeRef = currentBase || currentFrost;
    if(!cakeRef || !glbHasMesh(cakeRef)) return;
    cakeRef.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(cakeRef);
    const fullHeight = box.max.y - box.min.y;
    if(fullHeight < 0.01) return;

    const crust = deepCloneObject3D(cakeRef);
    const CRUST_COLOR = '#7A4A22'; // richer, clearly-visible graham-cracker brown
    crust.traverse(c=>{
        if(!c.isMesh) return;
        c.material = new THREE.MeshStandardMaterial({
            color: new THREE.Color(CRUST_COLOR),
            roughness: 0.90, metalness: 0.0, envMapIntensity: 0.30,
            // Stops the flicker/glitch: the crust's side wall previously sat at
            // the exact same radius as the cake's own side wall, so the GPU
            // couldn't decide which surface was in front (z-fighting). Nudging
            // the crust's depth value fixes that without moving it visually.
            polygonOffset: true,
            polygonOffsetFactor: -4,
            polygonOffsetUnits: -4,
        });
        c.castShadow = c.receiveShadow = true;
    });

// Thin slice — ~10% of the cake's height, clamped to a sensible range so
    // it reads as a crust layer rather than a second tier.
    const desiredThickness = Math.max(0.05, Math.min(0.14, fullHeight * 0.10));
    const sY = desiredThickness / fullHeight;
    // Only a hair wider than the cake — just enough to avoid sitting exactly
    // on the same surface as the cake wall (which caused the flicker). Keep
    // this small or the crust reads as an oversized skirt around the base.
    const sXZ = 1.006;
    crust.scale.set(crust.scale.x * sXZ, crust.scale.y * sY, crust.scale.z * sXZ);
    crust.updateMatrixWorld(true);

    // Re-align: bottom flush with the cake's own bottom, re-centered on X/Z
    // (widening the XZ scale above shifts the bounding box off-center).
    const newBox = new THREE.Box3().setFromObject(crust);
    const cakeCenter = box.getCenter(new THREE.Vector3());
    const crustCenter = newBox.getCenter(new THREE.Vector3());
    crust.position.y += (box.min.y - newBox.min.y) + 0.002;
    crust.position.x += cakeCenter.x - crustCenter.x;
    crust.position.z += cakeCenter.z - crustCenter.z;
    crust.updateMatrixWorld(true);

    sceneRoot.add(crust);
    currentCheesecakeCrust = crust;
}

// ── PER-TIER DECORATION FILTER (Two-tier / Three-tier only) ──
// Rings are built and fitted exactly as before; pieces on unselected tiers are just hidden,
// so the selected ones stay in the exact same position.
function _getTierTopYs(tierCount){
    const ref = currentBase || currentFrost;
    if(!ref) return null;
    ref.updateMatrixWorld(true);
    let tops = null;
    const groups = getTierGroups(ref);
    if(groups.length === tierCount){
        tops = groups.map(g => new THREE.Box3().setFromObject(g).max.y);
    } else {
        const b = new THREE.Box3().setFromObject(ref);
        try{
            const prof = _sliceSampleRadiusProfile(0, (b.min.x+b.max.x)/2, (b.min.z+b.max.z)/2, b.min.y, b.max.y, 90);
            const segs = _sliceDetectTierSegments(prof);
            if(segs.length === tierCount) tops = segs.map(s => prof[s.end].y);
        }catch(e){}
        if(!tops){
            tops = [];
            for(let i=0;i<tierCount;i++) tops.push(b.min.y + (b.max.y-b.min.y)*(i+1)/tierCount);
        }
    }
    return tops.sort((a,b)=>a-b);
}
// Splits one mesh that spans several tiers into one mesh per tier (by triangle height).
function _splitMeshByTier(mesh, tierOfY, tierCount){
    if(!mesh.parent) return [mesh];
    const src = mesh.geometry.index ? mesh.geometry.toNonIndexed() : mesh.geometry;
    const pos = src.attributes.position;
    mesh.updateMatrixWorld(true);
    const v = new THREE.Vector3();
    const buckets = Array.from({length:tierCount}, ()=>[]);
    for(let t=0; t<pos.count; t+=3){
        let cy = 0;
        for(let k=0;k<3;k++){ v.fromBufferAttribute(pos, t+k).applyMatrix4(mesh.matrixWorld); cy += v.y; }
        buckets[tierOfY(cy/3)].push(t);
    }
    const out = [];
    buckets.forEach((tris, ti)=>{
        if(!tris.length) return;
        const g = new THREE.BufferGeometry();
        Object.keys(src.attributes).forEach(name=>{
            const a = src.attributes[name], size = a.itemSize;
            const arr = new Float32Array(tris.length*3*size);
            let o = 0;
            tris.forEach(t=>{
                for(let k=0;k<3;k++){
                    const i = t+k;
                    arr[o++] = a.getX(i);
                    if(size>1) arr[o++] = a.getY(i);
                    if(size>2) arr[o++] = a.getZ(i);
                    if(size>3) arr[o++] = a.getW(i);
                }
            });
            g.setAttribute(name, new THREE.BufferAttribute(arr, size));
        });
        const mat = Array.isArray(mesh.material) ? mesh.material.map(m=>m.clone()) : mesh.material.clone();
        const piece = new THREE.Mesh(g, mat);
        piece.position.copy(mesh.position); piece.quaternion.copy(mesh.quaternion); piece.scale.copy(mesh.scale);
        piece.castShadow = mesh.castShadow; piece.receiveShadow = mesh.receiveShadow;
        piece.userData._tierIdx = ti;
        mesh.parent.add(piece);
        out.push(piece);
    });
    if(src !== mesh.geometry) src.dispose();
    mesh.parent.remove(mesh);
    return out;
}
function applyTierDecorFilter(st, rosettePieces){
    const tierCount = st.tier === 'Three-tier' ? 3 : 2;
    const tops = _getTierTopYs(tierCount);
    if(!tops) return;
    const gaps = tops.slice(1).map((t,i)=>t-tops[i]);
    const step = Math.min(...gaps);
    if(!(step > 0.05)) return;
    // A ring sits at the top rim of its own tier (its piping rises a little above it),
    // so a piece belongs to tier i until it is 40% of the way up the next tier.
    const tierOfY = y => { for(let i=0;i<tierCount-1;i++){ if(y <= tops[i] + 0.4*gaps[i]) return i; } return tierCount-1; };
    const allowedFor = key => {
        const a = ((st.tierDecor && st.tierDecor[key]) || []).filter(t=>t<tierCount);
        return new Set(a.length ? a : [...Array(tierCount).keys()]);
    };
    const box = new THREE.Box3();
    const filterGroup = (group, allowed)=>{
        if(!group) return;
        group.updateMatrixWorld(true);
        const meshes = [];
        group.traverse(c=>{ if(c.isMesh) meshes.push(c); });
        meshes.forEach(mesh=>{
            box.setFromObject(mesh);
            let targets = [mesh];
            if((box.max.y - box.min.y) > step*0.6 && tierOfY(box.min.y) !== tierOfY(box.max.y)){
                targets = _splitMeshByTier(mesh, tierOfY, tierCount);
            }
            targets.forEach(m=>{
                if(m.userData._tierIdx !== undefined){
                    m.visible = allowed.has(m.userData._tierIdx);
                } else {
                    box.setFromObject(m);
                    m.visible = allowed.has(tierOfY((box.min.y+box.max.y)/2));
                }
            });
        });
    };
    const fr = st.frostings || [];
    if(currentBase && currentFrost && currentFrost!==currentBase && fr.includes('Smooth Buttercream')) filterGroup(currentFrost, allowedFor('shell'));
    if(currentIcing && currentIcing!==currentBase && fr.includes('Sugar Icing')) filterGroup(currentIcing, allowedFor('icing'));
    if(fr.includes('Rosettes')) rosettePieces.forEach(p=>{ if(p.placement==='Border') filterGroup(p.glb, allowedFor('rosette')); });
    console.log('[TierDecor]', {tops, shell:[...allowedFor('shell')], icing:[...allowedFor('icing')], rosette:[...allowedFor('rosette')]});
    renderer.shadowMap.needsUpdate = true;
    if(typeof window._requestRender==='function') window._requestRender(1000);
}
