const sprinklesMeshes = { cylinder: null, pearl: null, chocoSprinkle: null, peanuts: null };
const sprinklePlacement = { cylinder: 'top', pearl: 'top', chocoSprinkle: 'top', peanuts: 'top' };
window._sprinklePlacement = sprinklePlacement;
// One Raycaster, reused for every sample point instead of allocating a new
// object (and its internal arrays) hundreds of times per sprinkle rebuild.
const _sharedSurfaceRaycaster = new THREE.Raycaster();
const _sharedSideRaycaster    = new THREE.Raycaster();

function _snapToSurface(x, z) {
    _sharedSurfaceRaycaster.set(
        new THREE.Vector3(x, 20, z),
        new THREE.Vector3(0, -1, 0)
    );
    const meshes = getSprinkleTargetMeshes();
    const hits = _sharedSurfaceRaycaster.intersectObjects(meshes, false);
    if (hits.length === 0) return null;
    hits.sort((a, b) => b.point.y - a.point.y);
    return hits[0].point.y;
}

function _snapToSide(cx, cz, angle, y) {
    const FAR    = 10.0;
    const origin = new THREE.Vector3(
        cx + Math.cos(angle) * FAR,
        y,
        cz + Math.sin(angle) * FAR
    );
    const dir = new THREE.Vector3(-Math.cos(angle), 0, -Math.sin(angle));
    _sharedSideRaycaster.set(origin, dir);
    _sharedSideRaycaster.far = FAR * 2;
    const meshes = getSprinkleTargetMeshes();
    const hits   = _sharedSideRaycaster.intersectObjects(meshes, false);
    if (hits.length === 0) return null;
    hits.sort((a, b) => a.distance - b.distance);
    return hits[0].point;
}

// ── Build a list of candidate top-surface points via dense grid raycasting ──
// This guarantees sprinkles only land on actual cake surface (works for heart, number, any shape)
function _buildSurfacePoints(density) {
    sceneRoot.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(sceneRoot);
    const cx  = (box.min.x + box.max.x) * 0.5;
    const cz  = (box.min.z + box.max.z) * 0.5;
    const rx  = (box.max.x - box.min.x) * 0.52;
    const rz  = (box.max.z - box.min.z) * 0.52;

    const points = []; // { x, y, z, isTop }
    const step   = density; // smaller = denser grid

    for (let xi = -rx; xi <= rx; xi += step) {
        for (let zi = -rz; zi <= rz; zi += step) {
            const wx = cx + xi + (Math.random() - 0.5) * step * 0.8;
            const wz = cz + zi + (Math.random() - 0.5) * step * 0.8;
            const wy = _snapToSurface(wx, wz);
            if (wy !== null) {
                points.push({ x: wx, y: wy, z: wz });
            }
        }
    }
    return points;
}
function buildCylinderSprinkles() {
    if (sprinklesMeshes.cylinder) {
        _disposeDecorGroup(sprinklesMeshes.cylinder);
        scene.remove(sprinklesMeshes.cylinder);
        sprinklesMeshes.cylinder = null;
    }

    const COLORS = [
        0xFF4466, 0xFF8C00, 0xFFD700, 0x44DD44,
        0x44AAFF, 0xAA44FF, 0xFF44CC, 0xFFFFFF,
        0xFF6699, 0x00CCFF, 0xFF3300, 0x99FF44,
    ];

    const group = new THREE.Group();
    const ROD_R = 0.010;
    const ROD_L = 0.052;

    // PERF: one shared rod geometry + one material per color, batched onto
    // the GPU via InstancedMesh — previously every rod allocated its own
    // CylinderGeometry + MeshStandardMaterial (up to ~440 unique GPU
    // resources for a single "both" placement on a busy cake), which was a
    // major contributor to FPS drops/crash risk on complex cakes. Placement,
    // jitter and per-piece orientation are unchanged; only how the results
    // are batched for rendering has changed.
    if (!window._sprinkleRodBaseGeo) {
        window._sprinkleRodBaseGeo = new THREE.CylinderGeometry(ROD_R, ROD_R, ROD_L, 7);
        window._sprinkleRodBaseGeo.userData.isSharedTemplate = true;
    }
    const rodGeo = window._sprinkleRodBaseGeo;
    const rodMats = COLORS.map(c => new THREE.MeshStandardMaterial({
        color: c, roughness: 0.28, metalness: 0.08, envMapIntensity: 1.0,
    }));
    const dummy = new THREE.Object3D();
    const byColor = COLORS.map(() => []);

    if (sprinklePlacement.cylinder === 'top' || sprinklePlacement.cylinder === 'both') {
        const topPoints = _buildSurfacePoints(0.095);
        for (let i = topPoints.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [topPoints[i], topPoints[j]] = [topPoints[j], topPoints[i]];
        }
        const topCount = Math.min(220, topPoints.length);
        for (let i = 0; i < topCount; i++) {
            const { x, y, z } = topPoints[i];
            const colorIdx = Math.floor(Math.random() * COLORS.length);
            dummy.position.set(x, y + ROD_R * 0.5, z);
            dummy.rotation.set((Math.random() - 0.5) * 0.12, Math.random() * Math.PI * 2, Math.PI / 2);
            dummy.scale.set(1, 1, 1);
            dummy.updateMatrix();
            byColor[colorIdx].push(dummy.matrix.clone());
        }
    }

    if (sprinklePlacement.cylinder === 'sides' || sprinklePlacement.cylinder === 'both') {
        sceneRoot.updateMatrixWorld(true);
        const cakeMeshesForBox = getSprinkleTargetMeshes();
        const cakeBox = new THREE.Box3();
        cakeMeshesForBox.forEach(m => cakeBox.expandByObject(m));
        if (cakeBox.isEmpty()) cakeBox.setFromObject(sceneRoot);
        const cakeCX  = (cakeBox.min.x + cakeBox.max.x) * 0.5;
        const cakeCZ  = (cakeBox.min.z + cakeBox.max.z) * 0.5;
        const cakeH   = cakeBox.max.y - cakeBox.min.y;
        // Stratified: divide wall into angle × height cells, place one per cell
        const ANGLE_SEGS = 32;  // slices around circumference
        const HEIGHT_SEGS = 7;  // rows from bottom to top
        for (let ai = 0; ai < ANGLE_SEGS; ai++) {
            for (let hi = 0; hi < HEIGHT_SEGS; hi++) {
                // Jitter within each cell for natural look
                const angleBase  = (ai / ANGLE_SEGS) * Math.PI * 2;
                const angleJitter = (Math.random() - 0.5) * (Math.PI * 2 / ANGLE_SEGS) * 0.85;
                const angle      = angleBase + angleJitter;
                const heightBase = 0.04 + (hi / HEIGHT_SEGS) * 0.88;
                const heightFrac = heightBase + Math.random() * (0.88 / HEIGHT_SEGS) * 0.85;
                const y = cakeBox.min.y + heightFrac * cakeH;
                const hit = _snapToSide(cakeCX, cakeCZ, angle, y);
                if (!hit) continue;
                const colorIdx = Math.floor(Math.random() * COLORS.length);
                // Lay the rod on its SIDE (tip the cylinder axis 90° off vertical),
                // then spin it randomly in the plane of the wall so each piece points
                // a different horizontal-ish direction — like a sprinkle stuck flat
                // against frosting, never poking straight out like a quill.
                const cylOut = ROD_R * 0.9; // sits mostly embedded, just barely proud of the wall
                dummy.position.set(
                    hit.x + Math.cos(angle) * cylOut,
                    hit.y + (Math.random() - 0.5) * 0.012,
                    hit.z + Math.sin(angle) * cylOut
                );
                dummy.rotation.set((Math.random() - 0.5) * 0.5, Math.random() * Math.PI * 2, Math.PI / 2);
                dummy.scale.set(1, 1, 1);
                dummy.updateMatrix();
                byColor[colorIdx].push(dummy.matrix.clone());
            }
        }
    }

    byColor.forEach((matrices, idx) => {
        if (matrices.length === 0) return;
        const inst = new THREE.InstancedMesh(rodGeo, rodMats[idx], matrices.length);
        inst.castShadow = true;
        matrices.forEach((m, i) => inst.setMatrixAt(i, m));
        inst.instanceMatrix.needsUpdate = true;
        group.add(inst);
    });

    scene.add(group);
    sprinklesMeshes.cylinder = group;
}
function buildPearlSprinkles() {
    if (sprinklesMeshes.pearl) {
        _disposeDecorGroup(sprinklesMeshes.pearl);
        scene.remove(sprinklesMeshes.pearl);
        sprinklesMeshes.pearl = null;
    }

    const PEARL_COLORS = [
        { color: 0xFFB8D0, emissive: 0xFF90B8 },
        { color: 0xB8E4FF, emissive: 0x80CCFF },
        { color: 0xFFFBD6, emissive: 0xFFF09A },
        { color: 0xFFD6F0, emissive: 0xFFAADD },
        { color: 0xD8F4FF, emissive: 0xAAE8FF },
        { color: 0xF4F0FF, emissive: 0xDDD0FF },
    ];

    const group     = new THREE.Group();
    const PEARL_MIN = 0.015;
    const PEARL_MAX = 0.024;

    // PERF: one shared unit-sphere geometry (per-instance size applied via
    // the instance's scale, exactly like the surface radius used to vary
    // per-mesh) instead of a fresh SphereGeometry for every pearl, batched
    // into InstancedMeshes grouped by color. Top and side placements keep
    // their own material set since they use slightly different
    // emissiveIntensity, matching the original look exactly.
    if (!window._sprinklePearlBaseGeo) {
        window._sprinklePearlBaseGeo = new THREE.SphereGeometry(1, 9, 9);
        window._sprinklePearlBaseGeo.userData.isSharedTemplate = true;
    }
    const pearlGeo = window._sprinklePearlBaseGeo;
    const makePearlMats = (intensity) => PEARL_COLORS.map(pal => new THREE.MeshStandardMaterial({
        color:             new THREE.Color(pal.color),
        emissive:          new THREE.Color(pal.emissive),
        emissiveIntensity: intensity,
        roughness:         0.05,
        metalness:         0.12,
        envMapIntensity:   1.6,
    }));
    const topMats  = makePearlMats(0.08);
    const sideMats = makePearlMats(0.07);
    const dummy = new THREE.Object3D();
    const byColorTop  = PEARL_COLORS.map(() => []);
    const byColorSide = PEARL_COLORS.map(() => []);

if (sprinklePlacement.pearl === 'top' || sprinklePlacement.pearl === 'both') {
        const topPoints = _buildSurfacePoints(0.085);
        for (let i = topPoints.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [topPoints[i], topPoints[j]] = [topPoints[j], topPoints[i]];
        }
        const topCount = Math.min(180, topPoints.length);
        for (let i = 0; i < topCount; i++) {
            const { x, y, z } = topPoints[i];
            const colorIdx = Math.floor(Math.random() * PEARL_COLORS.length);
            const size = PEARL_MIN + Math.random() * (PEARL_MAX - PEARL_MIN);
            dummy.position.set(x, y + size * 0.5, z);
            dummy.rotation.set(0, 0, 0);
            dummy.scale.set(size, size, size);
            dummy.updateMatrix();
            byColorTop[colorIdx].push(dummy.matrix.clone());
        }
    }

if (sprinklePlacement.pearl === 'sides' || sprinklePlacement.pearl === 'both') {
        sceneRoot.updateMatrixWorld(true);
        const cakeMeshesForBox2 = getSprinkleTargetMeshes();
        const cakeBox = new THREE.Box3();
        cakeMeshesForBox2.forEach(m => cakeBox.expandByObject(m));
        if (cakeBox.isEmpty()) cakeBox.setFromObject(sceneRoot);
        const cakeCX  = (cakeBox.min.x + cakeBox.max.x) * 0.5;
        const cakeCZ  = (cakeBox.min.z + cakeBox.max.z) * 0.5;
        const cakeH   = cakeBox.max.y - cakeBox.min.y;
  // Stratified: divide wall into angle × height cells, place one per cell
        const ANGLE_SEGS_P  = 30;  // slices around circumference
        const HEIGHT_SEGS_P = 7;   // rows from bottom to top
        for (let ai = 0; ai < ANGLE_SEGS_P; ai++) {
            for (let hi = 0; hi < HEIGHT_SEGS_P; hi++) {
                const angleBase   = (ai / ANGLE_SEGS_P) * Math.PI * 2;
                const angleJitter = (Math.random() - 0.5) * (Math.PI * 2 / ANGLE_SEGS_P) * 0.85;
                const angle       = angleBase + angleJitter;
                const heightBase  = 0.04 + (hi / HEIGHT_SEGS_P) * 0.88;
                const heightFrac  = heightBase + Math.random() * (0.88 / HEIGHT_SEGS_P) * 0.85;
                const y = cakeBox.min.y + heightFrac * cakeH;
                const hit = _snapToSide(cakeCX, cakeCZ, angle, y);
                if (!hit) continue;
                const colorIdx = Math.floor(Math.random() * PEARL_COLORS.length);
                const size = PEARL_MIN + Math.random() * (PEARL_MAX - PEARL_MIN);
                const pearlOut = size * 0.5;
                dummy.position.set(
                    hit.x + Math.cos(angle) * pearlOut,
                    hit.y,
                    hit.z + Math.sin(angle) * pearlOut
                );
                dummy.rotation.set(0, 0, 0);
                dummy.scale.set(size, size, size);
                dummy.updateMatrix();
                byColorSide[colorIdx].push(dummy.matrix.clone());
            }
        }
    }

    byColorTop.forEach((matrices, idx) => {
        if (matrices.length === 0) return;
        const inst = new THREE.InstancedMesh(pearlGeo, topMats[idx], matrices.length);
        inst.castShadow = true;
        matrices.forEach((m, i) => inst.setMatrixAt(i, m));
        inst.instanceMatrix.needsUpdate = true;
        group.add(inst);
    });
    byColorSide.forEach((matrices, idx) => {
        if (matrices.length === 0) return;
        const inst = new THREE.InstancedMesh(pearlGeo, sideMats[idx], matrices.length);
        inst.castShadow = true;
        matrices.forEach((m, i) => inst.setMatrixAt(i, m));
        inst.instanceMatrix.needsUpdate = true;
        group.add(inst);
    });

    scene.add(group);
    sprinklesMeshes.pearl = group;
}

function buildChocoSprinkles() {
    if (sprinklesMeshes.chocoSprinkle) {
        _disposeDecorGroup(sprinklesMeshes.chocoSprinkle);
        scene.remove(sprinklesMeshes.chocoSprinkle);
        sprinklesMeshes.chocoSprinkle = null;
    }
    const CHOCO_COLOR = 0x2A1206;
    const group = new THREE.Group();
    const ROD_R = 0.010;
    const ROD_L = 0.050;

    // PERF: shared geometry + a single material (choco sprinkles are all one
    // color) batched into one InstancedMesh — was up to ~440 unique
    // geometries/materials for one draw call's worth of visual result.
    if (!window._chocoSprinkleBaseGeo) {
        window._chocoSprinkleBaseGeo = new THREE.CylinderGeometry(ROD_R, ROD_R, ROD_L, 7);
        window._chocoSprinkleBaseGeo.userData.isSharedTemplate = true;
    }
    const chocoGeo = window._chocoSprinkleBaseGeo;
    const chocoMat = new THREE.MeshStandardMaterial({ color: CHOCO_COLOR, roughness: 0.32, metalness: 0.06, envMapIntensity: 0.85 });
    const dummy = new THREE.Object3D();
    const matrices = [];

    if (sprinklePlacement.chocoSprinkle === 'top' || sprinklePlacement.chocoSprinkle === 'both') {
        const topPoints = _buildSurfacePoints(0.095);
        for (let i = topPoints.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [topPoints[i], topPoints[j]] = [topPoints[j], topPoints[i]];
        }
        const topCount = Math.min(220, topPoints.length);
        for (let i = 0; i < topCount; i++) {
            const { x, y, z } = topPoints[i];
            dummy.position.set(x, y + ROD_R * 0.5, z);
            dummy.rotation.set((Math.random() - 0.5) * 0.12, Math.random() * Math.PI * 2, Math.PI / 2);
            dummy.scale.set(1, 1, 1);
            dummy.updateMatrix();
            matrices.push(dummy.matrix.clone());
        }
    }
    if (sprinklePlacement.chocoSprinkle === 'sides' || sprinklePlacement.chocoSprinkle === 'both') {
        sceneRoot.updateMatrixWorld(true);
        const cakeMeshesForBox = getSprinkleTargetMeshes();
        const cakeBox = new THREE.Box3();
        cakeMeshesForBox.forEach(m => cakeBox.expandByObject(m));
        if (cakeBox.isEmpty()) cakeBox.setFromObject(sceneRoot);
        const cakeCX = (cakeBox.min.x + cakeBox.max.x) * 0.5;
        const cakeCZ = (cakeBox.min.z + cakeBox.max.z) * 0.5;
        const cakeH  = cakeBox.max.y - cakeBox.min.y;
        const ANGLE_SEGS = 32, HEIGHT_SEGS = 7;
        for (let ai = 0; ai < ANGLE_SEGS; ai++) {
            for (let hi = 0; hi < HEIGHT_SEGS; hi++) {
                const angleBase = (ai / ANGLE_SEGS) * Math.PI * 2;
                const angle = angleBase + (Math.random() - 0.5) * (Math.PI * 2 / ANGLE_SEGS) * 0.85;
                const heightBase = 0.04 + (hi / HEIGHT_SEGS) * 0.88;
                const heightFrac = heightBase + Math.random() * (0.88 / HEIGHT_SEGS) * 0.85;
                const y = cakeBox.min.y + heightFrac * cakeH;
                const hit = _snapToSide(cakeCX, cakeCZ, angle, y);
                if (!hit) continue;
                // Lay the rod on its side and spin it randomly in the wall's plane —
                // flush against the frosting, random horizontal-ish orientation,
                // never poking straight outward.
                const cylOut = ROD_R * 0.9;
                dummy.position.set(hit.x + Math.cos(angle) * cylOut, hit.y + (Math.random() - 0.5) * 0.012, hit.z + Math.sin(angle) * cylOut);
                dummy.rotation.set((Math.random() - 0.5) * 0.5, Math.random() * Math.PI * 2, Math.PI / 2);
                dummy.scale.set(1, 1, 1);
                dummy.updateMatrix();
                matrices.push(dummy.matrix.clone());
            }
        }
    }
    if (matrices.length > 0) {
        const inst = new THREE.InstancedMesh(chocoGeo, chocoMat, matrices.length);
        inst.castShadow = true;
        matrices.forEach((m, i) => inst.setMatrixAt(i, m));
        inst.instanceMatrix.needsUpdate = true;
        group.add(inst);
    }
    scene.add(group);
    sprinklesMeshes.chocoSprinkle = group;
}
function buildCrushedPeanuts() {
    if (sprinklesMeshes.peanuts) {
        _disposeDecorGroup(sprinklesMeshes.peanuts);
        scene.remove(sprinklesMeshes.peanuts);
        sprinklesMeshes.peanuts = null;
    }
    const PEANUT_COLORS = [0xC89860, 0xB8804A, 0xD4A66E, 0xA06E3C];
    const group = new THREE.Group();
    const CHUNK_MIN = 0.008;
    const CHUNK_MAX = 0.016;
    const CLUSTER_PER_POINT = 15; // same cluster count for top AND sides so density matches on both

    // One shared unit geometry, reused (scaled per-instance) across every peanut —
    // avoids allocating thousands of separate BufferGeometries.
    if (!window._peanutBaseGeo) window._peanutBaseGeo = new THREE.DodecahedronGeometry(1, 0);
    const baseGeo = window._peanutBaseGeo;
    const mats = PEANUT_COLORS.map(c => new THREE.MeshStandardMaterial({
        color: c, roughness: 0.62, metalness: 0.01, envMapIntensity: 0.55,
    }));

    // Gather placement transforms first (cheap raycasts), batch into InstancedMesh after.
    const byColor = [[], [], [], []];
    const dummy = new THREE.Object3D();

    if (sprinklePlacement.peanuts === 'top' || sprinklePlacement.peanuts === 'both') {
        const topPoints = _buildSurfacePoints(0.095); // identical raycast cost to Cylinder Sprinkles
        for (let i = topPoints.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [topPoints[i], topPoints[j]] = [topPoints[j], topPoints[i]];
        }
        const topCount = Math.min(220, topPoints.length); // same cap as Cylinder Sprinkles
        for (let i = 0; i < topCount; i++) {
            const { x, y, z } = topPoints[i];
            for (let c = 0; c < CLUSTER_PER_POINT; c++) {
                const size = CHUNK_MIN + Math.random() * (CHUNK_MAX - CHUNK_MIN);
                const jx = (Math.random() - 0.5) * 0.06;
                const jz = (Math.random() - 0.5) * 0.06;
                const colorIdx = Math.floor(Math.random() * PEANUT_COLORS.length);
                dummy.position.set(x + jx, y + size * 0.28, z + jz);
                dummy.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
                dummy.scale.set(size, size * 0.62, size);
                dummy.updateMatrix();
                byColor[colorIdx].push(dummy.matrix.clone());
            }
        }
    }

    if (sprinklePlacement.peanuts === 'sides' || sprinklePlacement.peanuts === 'both') {
        sceneRoot.updateMatrixWorld(true);
        const cakeMeshesForBox = getSprinkleTargetMeshes();
        const cakeBox = new THREE.Box3();
        cakeMeshesForBox.forEach(m => cakeBox.expandByObject(m));
        if (cakeBox.isEmpty()) cakeBox.setFromObject(sceneRoot);
        const cakeCX = (cakeBox.min.x + cakeBox.max.x) * 0.5;
        const cakeCZ = (cakeBox.min.z + cakeBox.max.z) * 0.5;
        const cakeH  = cakeBox.max.y - cakeBox.min.y;
        const ANGLE_SEGS = 40, HEIGHT_SEGS = 11; // close to Cylinder Sprinkles' side cost, slightly denser grid
        for (let ai = 0; ai < ANGLE_SEGS; ai++) {
            for (let hi = 0; hi < HEIGHT_SEGS; hi++) {
                const angleBase = (ai / ANGLE_SEGS) * Math.PI * 2;
                const angle = angleBase + (Math.random() - 0.5) * (Math.PI * 2 / ANGLE_SEGS) * 0.85;
                const heightBase = 0.04 + (hi / HEIGHT_SEGS) * 0.88;
                const heightFrac = heightBase + Math.random() * (0.88 / HEIGHT_SEGS) * 0.85;
                const y = cakeBox.min.y + heightFrac * cakeH;
                const hit = _snapToSide(cakeCX, cakeCZ, angle, y);
                if (!hit) continue;
                // Wide jitter per cluster point — wider than the grid spacing itself —
                // so neighboring clusters overlap and blend into a continuous random
                // scatter (matching the top's organic look) instead of visible dotted
                // rows/columns tracing the raycast grid.
                const angleStep = (Math.PI * 2 / ANGLE_SEGS);
                const heightStep = (0.88 / HEIGHT_SEGS) * cakeH;
                for (let c = 0; c < CLUSTER_PER_POINT; c++) {
                    const size = CHUNK_MIN + Math.random() * (CHUNK_MAX - CHUNK_MIN);
                    const chunkOut = size * 0.5;
                    const jAngle = angle + (Math.random() - 0.5) * angleStep * 1.3;
                    const jY = (Math.random() - 0.5) * heightStep * 1.3;
                    const colorIdx = Math.floor(Math.random() * PEANUT_COLORS.length);
                    dummy.position.set(hit.x + Math.cos(jAngle) * chunkOut, hit.y + jY, hit.z + Math.sin(jAngle) * chunkOut);
                    dummy.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
                    dummy.scale.set(size, size, size);
                    dummy.updateMatrix();
                    byColor[colorIdx].push(dummy.matrix.clone());
                }
            }
        }
    }

    // Batch each color into a single InstancedMesh — 4 draw calls total, however
    // many thousand peanuts are placed.
    byColor.forEach((matrices, idx) => {
        if (matrices.length === 0) return;
        const inst = new THREE.InstancedMesh(baseGeo, mats[idx], matrices.length);
        inst.castShadow = true;
        matrices.forEach((m, i) => inst.setMatrixAt(i, m));
        inst.instanceMatrix.needsUpdate = true;
        group.add(inst);
    });

    scene.add(group);
    sprinklesMeshes.peanuts = group;
}
function clearSprinkles(type) {
    if (type === 'cylinder' && sprinklesMeshes.cylinder) {
        _disposeDecorGroup(sprinklesMeshes.cylinder);
        scene.remove(sprinklesMeshes.cylinder);
        sprinklesMeshes.cylinder = null;
    }
    if (type === 'pearl' && sprinklesMeshes.pearl) {
        _disposeDecorGroup(sprinklesMeshes.pearl);
        scene.remove(sprinklesMeshes.pearl);
        sprinklesMeshes.pearl = null;
    }
    if (type === 'chocoSprinkle' && sprinklesMeshes.chocoSprinkle) {
        _disposeDecorGroup(sprinklesMeshes.chocoSprinkle);
        scene.remove(sprinklesMeshes.chocoSprinkle);
        sprinklesMeshes.chocoSprinkle = null;
    }
    if (type === 'peanuts' && sprinklesMeshes.peanuts) {
        _disposeDecorGroup(sprinklesMeshes.peanuts);
        scene.remove(sprinklesMeshes.peanuts);
        sprinklesMeshes.peanuts = null;
    }
}

window.buildCylinderSprinkles = buildCylinderSprinkles;
window.buildPearlSprinkles    = buildPearlSprinkles;
window.buildChocoSprinkles    = buildChocoSprinkles;
window.buildCrushedPeanuts    = buildCrushedPeanuts;
window.clearSprinkles         = clearSprinkles;

// Merges many static decorative pieces (Kiwi/Banana GLB clones) into ONE mesh,
// so a large "Full" pile costs a single draw call instead of one per piece —
// this is the actual fix for the Kiwi/Banana lag, not just a resolution/fps
// trick. All pieces are baked to one shared material (visually fine for tiny
// decorative fruit slices) since merging per-original-material would still
// leave one draw call per piece (each GLB clone gets its own cloned material).
function mergeStaticMeshGroupsSingleMaterial(groups){
    // IMPORTANT: a fruit model like Kiwi is made of several sub-meshes each
    // with its OWN material (e.g. green skin ring, white flesh, black seeds).
    // Taking only the first material and applying it to everything was what
    // turned the merged pile into one flat green blob. Instead, every
    // sub-mesh's vertices are appended with a geometry "group" pointing at
    // its own material index, so the final mesh keeps all the original
    // colors/textures — still just a handful of draw calls (one per unique
    // material used across the whole pile), not one per piece.
    const positions = [], normals = [], uvs = [];
    const materials = [];
    const materialGroups = []; // {start, count, materialIndex}
    const v = new THREE.Vector3(), n = new THREE.Vector3();
    groups.forEach(group=>{
        group.updateMatrixWorld(true);
        group.traverse(node=>{
            if(!node.isMesh) return;
            const geo = node.geometry;
            if(!geo || !geo.attributes || !geo.attributes.position) return;
            const nodeMat = Array.isArray(node.material) ? node.material[0] : node.material;
            if(!nodeMat) return;
            const materialIndex = materials.length;
            materials.push(nodeMat.clone());

            const nonIndexed = geo.index ? geo.toNonIndexed() : geo;
            const posAttr = nonIndexed.attributes.position;
            const normAttr = nonIndexed.attributes.normal;
            const uvAttr = nonIndexed.attributes.uv;
            const matWorld = node.matrixWorld;
            const normalMat = new THREE.Matrix3().getNormalMatrix(matWorld);

            const startVertex = positions.length / 3;
            for(let i=0;i<posAttr.count;i++){
                v.fromBufferAttribute(posAttr, i).applyMatrix4(matWorld);
                positions.push(v.x, v.y, v.z);
                if(normAttr){ n.fromBufferAttribute(normAttr, i).applyMatrix3(normalMat).normalize(); }
                else { n.set(0,1,0); }
                normals.push(n.x, n.y, n.z);
                if(uvAttr){ uvs.push(uvAttr.getX(i), uvAttr.getY(i)); } else { uvs.push(0,0); }
            }
            const vertexCount = posAttr.count;
            materialGroups.push({ start: startVertex, count: vertexCount, materialIndex });
            if(geo.index) nonIndexed.dispose();
        });
    });
    if(materials.length===0 || positions.length===0) return null;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions,3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals,3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs,2));
    materialGroups.forEach(g=>geo.addGroup(g.start, g.count, g.materialIndex));
    const mesh = new THREE.Mesh(geo, materials);
    mesh.castShadow = false; mesh.receiveShadow = false;
    const wrapper = new THREE.Group();
    wrapper.add(mesh);
    return wrapper;
}

// ── GRAM-BASED FRUITS (Mango Cube / Kiwi / Peach / Banana) — placement & scatter ──
window._gramFruitGroups = window._gramFruitGroups || {};
window._gramFruitGrams = window._gramFruitGrams || {};
window._gramFruitPlacement = window._gramFruitPlacement || {
    'Mango Slice':'middle', 'Kiwi Slice':'middle', 'Peach Slice':'middle', 'Banana Slice':'middle',
};
// Same raycast the sprinkles system uses, but also returns the surface
// normal at the hit point — needed so a placed piece can be tilted to lie
// flush against a curved/sloped cake surface instead of always sitting
// perfectly flat (which is what made the mango cubes look like they were
// floating above the frosting instead of resting in it).
function _snapToSurfaceWithNormal(x, z){
    _sharedSurfaceRaycaster.set(
        new THREE.Vector3(x, 20, z),
        new THREE.Vector3(0, -1, 0)
    );
    const meshes = getSprinkleTargetMeshes();
    const hits = _sharedSurfaceRaycaster.intersectObjects(meshes, false);
    if (hits.length === 0) return null;
    hits.sort((a, b) => b.point.y - a.point.y);
    const hit = hits[0];
    let normal = new THREE.Vector3(0,1,0);
    if(hit.face){
        normal = hit.face.normal.clone();
        if(hit.object && hit.object.matrixWorld){
            const nm = new THREE.Matrix3().getNormalMatrix(hit.object.matrixWorld);
            normal.applyMatrix3(nm).normalize();
        }
        if(normal.y < 0) normal.negate();
        // Fruit should lie flat: pull the normal mostly toward straight up so piped
        // borders / bumps don't tilt pieces. Bundt keeps its real slope.
        const _isBundtFruit = (typeof state !== 'undefined' && state.shape === 'Bundt');
        if(!_isBundtFruit){
            normal.lerp(new THREE.Vector3(0,1,0), 0.85).normalize();
        }
    }
    return { point: hit.point, normal };
}
// Uses the real cake mesh (not the plate/stand) so radius/center are accurate.
function _getCakeMetricsForFruits(){
    const ref = currentBase || currentFrost || currentIcing;
    let box;
    if(ref){
        ref.updateMatrixWorld(true);
        box = new THREE.Box3().setFromObject(ref);
    } else {
        sceneRoot.updateMatrixWorld(true);
        box = new THREE.Box3().setFromObject(sceneRoot);
    }
    const cx=(box.min.x+box.max.x)*0.5, cz=(box.min.z+box.max.z)*0.5;
    const r=Math.max(box.max.x-box.min.x, box.max.z-box.min.z)*0.5;
    return {cx,cz,r:r>0.001?r:1.0};
}

// If a target angle/radius happens to miss the cake surface (e.g. near a
// square/heart corner), shrink inward a few times instead of dropping the point.
function _raycastFruitPointAt(cx, cz, angle, radius){
    let rr = radius;
    for(let attempt=0; attempt<7; attempt++){
        const wx = cx + Math.cos(angle)*rr;
        const wz = cz + Math.sin(angle)*rr;
        const hit = _snapToSurfaceWithNormal(wx, wz);
        if(hit) return hit;
        rr *= 0.86;
    }
    return null;
}


function _findCakeEdgeRadiusAtAngle(cx, cz, angle){
    // Horizontal raycast toward the center at this angle, just under the
    // cake's top edge, to find the REAL distance to the cake surface — this
    // lets a "Border" ring hug the actual shape (round, square, heart, etc.)
    // instead of always tracing a circle.
    const ref = currentBase || currentFrost || currentIcing;
    if(!ref) return _getCakeMetricsForFruits().r;
    ref.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(ref);
    const yTop = box.max.y - (box.max.y - box.min.y) * 0.06;
    const dirX = Math.cos(angle), dirZ = Math.sin(angle);
    const FAR = Math.max(box.max.x - box.min.x, box.max.z - box.min.z) * 1.6 + 2.0;
    const origin = new THREE.Vector3(cx + dirX * FAR, yTop, cz + dirZ * FAR);
    const rayDir = new THREE.Vector3(-dirX, 0, -dirZ);
    const rc = new THREE.Raycaster(origin, rayDir, 0, FAR * 2);
    const meshes = getSprinkleTargetMeshes();
    const hits = rc.intersectObjects(meshes, false);
    if (hits.length === 0) return _getCakeMetricsForFruits().r;
    hits.sort((a, b) => a.distance - b.distance);
    const hp = hits[0].point;
    return Math.sqrt((hp.x - cx) * (hp.x - cx) + (hp.z - cz) * (hp.z - cz));
}
// ── BUNDT ONLY: top row = one piece on each ridge crest, lower row = one piece between every two crests ──
function _buildBundtLobePoints(cx, cz, r){
    const SAMPLES = 360;          // 1° per sample
    const RING_FRAC = 0.74;       // TOP ROW: ring radius as a fraction of the cake radius
    const LOWER_RING_FRAC = 0.70; // LOWER ROW: higher = lower down the outside of the Bundt, lower = closer to the top
    const FALLBACK_LOBES = 12;    // used only if the ridges can't be detected
    const SMOOTH = 3;             // moving-average half-width (samples)
    const PEAK_WINDOW = 12;       // a crest must be the highest within ±12°

    const hits = new Array(SAMPLES).fill(null);
    let validCount = 0, validSum = 0;
    for(let i=0;i<SAMPLES;i++){
        const angle = (i/SAMPLES)*Math.PI*2;
        const hit = _raycastFruitPointAt(cx, cz, angle, r*RING_FRAC);
        if(hit){ hits[i] = hit; validCount++; validSum += hit.point.y; }
    }
    if(validCount < SAMPLES*0.8) return [];
    const meanY = validSum / validCount;
    const rawY = hits.map(h => h ? h.point.y : meanY);

    const ys = rawY.map((_, i)=>{
        let s = 0, n = 0;
        for(let k=-SMOOTH;k<=SMOOTH;k++){ s += rawY[(i+k+SAMPLES)%SAMPLES]; n++; }
        return s/n;
    });
    const minY = Math.min(...ys), maxY = Math.max(...ys);

    let peaks = [];
    if(maxY - minY > 0.008){
        for(let i=0;i<SAMPLES;i++){
            let isPeak = true;
            for(let k=1;k<=PEAK_WINDOW && isPeak;k++){
                if(ys[(i-k+SAMPLES)%SAMPLES] >= ys[i]) isPeak = false;
                if(ys[(i+k)%SAMPLES] > ys[i])          isPeak = false;
            }
            if(isPeak) peaks.push(i);
        }
    }
