    panel.style.cssText = 'display:none;position:absolute;top:58px;left:14px;z-index:50;width:260px;border-radius:14px;overflow:hidden;border:1.5px solid rgba(196,154,60,.30);box-shadow:0 4px 20px rgba(59,31,14,0.35);';

  function getModels(type){
        if(type==='ferrero') return typeof window.getFerreroModels==='function'?window.getFerreroModels():[];
        if(type==='kitkat')  return typeof window.getKitkatModels ==='function'?window.getKitkatModels() :[];
        if(type==='oreo')    return typeof window.getOreoModels   ==='function'?window.getOreoModels()   :[];
        if(type==='barshard')return typeof window.getBarShardModels==='function'?window.getBarShardModels():[];
        if(type==='toblerone')return typeof window.getTobleroneModels==='function'?window.getTobleroneModels():[];
        return [];
    }
function getDeg(m){
        return Math.round((m.group.rotation.z * 180 / Math.PI + 360) % 360);
    }
    function getDegY(m){
        return Math.round((m.group.rotation.y * 180 / Math.PI + 360) % 360);
    }

    const rangeY    = document.getElementById('chocoRotInlineRangeY');
    const degLabelY = document.getElementById('chocoRotInlineDegY');

     function showChocoPanel(type, idx){
        activeChocoType = type;
        activeChocoPanelIdx = idx;
        const models = getModels(type);
        const m = models[idx];
        if(!m) return;
        const em = CHOCO_EMOJI[type] || '🍫';
        const deg = getDeg(m);
        const degY = getDegY(m);
        emojiEl.textContent = em;
        preview.textContent = em;
        nameEl.textContent = CHOCO_NAME[type] || type;
        range.value = deg;
        degLabel.textContent = deg + '°';
        preview.style.transform = `rotate(${deg}deg)`;
        rangeY.value = degY;
        degLabelY.textContent = degY + '°';
        panel.style.display = 'block';
        if(typeof window._requestRender==='function') window._requestRender(2000);
    }

    function hideChocoPanel(){
        panel.style.display = 'none';
        activeChocoPanelIdx = -1;
        activeChocoType = null;
    }
range.addEventListener('input', function(){
        const d = parseInt(this.value);
        degLabel.textContent = d + '°';
        preview.style.transform = `rotate(${d}deg)`;
        const models = getModels(activeChocoType);
        const m = models[activeChocoPanelIdx];
        if(m){ m.group.rotation.z = d * Math.PI / 180; }
        if(typeof window._requestRender==='function') window._requestRender(500);
    });
    rangeY.addEventListener('input', function(){
        const d = parseInt(this.value);
        degLabelY.textContent = d + '°';
        const models = getModels(activeChocoType);
        const m = models[activeChocoPanelIdx];
        if(m){ m.group.rotation.y = d * Math.PI / 180; }
        if(typeof window._requestRender==='function') window._requestRender(500);
    });
    document.querySelectorAll('.choco-rot-inline-preset').forEach(btn => {
        btn.addEventListener('click', () => {
            const d = parseInt(btn.dataset.deg);
            range.value = d; degLabel.textContent = d + '°';
            preview.style.transform = `rotate(${d}deg)`;
            const models = getModels(activeChocoType);
            const m = models[activeChocoPanelIdx];
            if(m){ m.group.rotation.z = d * Math.PI / 180; }
            if(typeof window._requestRender==='function') window._requestRender(500);
        });
    });
document.getElementById('chocoRotInlineApply').addEventListener('click', () => {
        const deg = parseInt(range.value);
        const em = emojiEl.textContent;
        showToast(`${em} Rotated ${deg}°`, 1600);
        hideChocoPanel();
    });

    document.getElementById('chocoRotInlineDelete').addEventListener('click', () => {
        const type = activeChocoType;
        const idx  = activeChocoPanelIdx;
        const em   = CHOCO_EMOJI[type]  || '🍫';
        const name = CHOCO_NAME[type]   || type;
     const removeFnMap = {
            ferrero:   window.removeFerreroModel,
            kitkat:    window.removeKitkatModel,
            oreo:      window.removeOreoModel,
            barshard:  window.removeBarShardModel,
            toblerone: window.removeTobleroneModel,
        };
        const removeFn = removeFnMap[type];
        if (typeof removeFn === 'function') removeFn(idx);
        hideChocoPanel();
        showToast(`${em} ${name} removed`, 1800);
        if (typeof window._updateAll === 'function') window._updateAll();
    });
document.getElementById('chocoRotInlineReset').addEventListener('click', () => {
        range.value = 0; degLabel.textContent = '0°';
        rangeY.value = 0; degLabelY.textContent = '0°';
        preview.style.transform = 'rotate(0deg)';
        const models = getModels(activeChocoType);
        const m = models[activeChocoPanelIdx];
        if(m){ m.group.rotation.z = 0; m.group.rotation.y = 0; }
        if(typeof window._requestRender==='function') window._requestRender(500);
    });
    document.getElementById('chocoRotInlineClose').addEventListener('click', hideChocoPanel);
    document.addEventListener('keydown', e => { if(e.key === 'Escape') hideChocoPanel(); });

window._showChocoRotatePanel = showChocoPanel;
    window._hideChocoRotatePanel = hideChocoPanel;
})();
// ── CHARACTER TOPPER MOVE/ROTATE PANEL (works per placed instance) ──
(function(){
    const panel    = document.getElementById('characterMovePanel');
    const range    = document.getElementById('characterMovePanelRange');
    const degLabel = document.getElementById('characterMovePanelDeg');
    const nameEl   = document.getElementById('characterMovePanelName');
    let activeIdx  = -1;

    const viewer = document.getElementById('viewerEl');
    if(viewer) viewer.appendChild(panel);
    panel.style.cssText = 'display:none;position:absolute;top:58px;left:14px;z-index:50;width:260px;border-radius:14px;overflow:hidden;border:1.5px solid rgba(90,110,196,.35);box-shadow:0 4px 20px rgba(30,15,5,0.35);';

    function refreshDeg(){
        const d = typeof window.getCharacterYRotationDeg==='function' ? window.getCharacterYRotationDeg(activeIdx) : 0;
        range.value = d;
        degLabel.textContent = d + '°';
    }
    function refreshSizeButtons(){
        const models = typeof window.getCharacterModels==='function' ? window.getCharacterModels() : [];
        const m = models[activeIdx];
        const current = m ? (m.sizeInches || 4) : 4;
        document.querySelectorAll('.character-move-size').forEach(btn=>{
            const on = parseInt(btn.dataset.size) === current;
            btn.style.background = on ? 'var(--caramel)' : 'var(--cream)';
            btn.style.color = on ? '#fff' : 'var(--brown-mid)';
        });
    }
    function showPanel(idx){
        activeIdx = idx;
        const models = typeof window.getCharacterModels==='function' ? window.getCharacterModels() : [];
        const m = models[idx];
        nameEl.textContent = m ? m.key : 'character';
        refreshDeg();
        refreshSizeButtons();
        panel.style.display = 'block';
        window._lastPlacedCharacterIdx = idx;
    }
    function hidePanel(){ panel.style.display = 'none'; activeIdx = -1; }
    document.querySelectorAll('.character-move-size').forEach(btn=>{
        btn.addEventListener('click', ()=>{
            const sz = parseInt(btn.dataset.size);
            if(activeIdx>=0 && typeof window.resizeCharacterModel==='function' && window.resizeCharacterModel(activeIdx, sz)){
                refreshSizeButtons();
                if(typeof window._updateAll === 'function') window._updateAll();
                if(typeof showToast === 'function') showToast(`📏 Resized to ${sz}"`, 1400);
            }
        });
    });

    range.addEventListener('input', function(){
        const d = parseInt(this.value);
        degLabel.textContent = d + '°';
        if(typeof window.setCharacterYRotation==='function') window.setCharacterYRotation(activeIdx, d);
        if(typeof window._requestRender==='function') window._requestRender(500);
    });
    document.querySelectorAll('.character-move-preset').forEach(btn=>{
        btn.addEventListener('click', ()=>{
            const d = parseInt(btn.dataset.deg);
            range.value = d; degLabel.textContent = d + '°';
            if(typeof window.setCharacterYRotation==='function') window.setCharacterYRotation(activeIdx, d);
            if(typeof window._requestRender==='function') window._requestRender(500);
        });
    });
    document.getElementById('characterMovePanelReset').addEventListener('click', ()=>{
        range.value = 0; degLabel.textContent = '0°';
        if(typeof window.setCharacterYRotation==='function') window.setCharacterYRotation(activeIdx, 0);
        if(typeof window._requestRender==='function') window._requestRender(500);
    });
    document.getElementById('characterMovePanelDelete').addEventListener('click', ()=>{
        if(activeIdx>=0 && typeof window.removeCharacterModel==='function') window.removeCharacterModel(activeIdx);
        window._lastPlacedCharacterIdx = -1;
        hidePanel();
        if(typeof window.getCharacterModels==='function'){
            const remaining = window.getCharacterModels().length;
            const badge = document.getElementById('characterActiveBadge');
            if(remaining===0 && typeof state !== 'undefined'){
                state.addons.delete('Character Topper');
                const btn = document.getElementById('characterToggleBtn');
                if(btn) btn.classList.remove('active');
                if(badge) badge.textContent = 'None placed yet — tap a character to add';
            } else if(badge){
                badge.textContent = `${remaining} placed — tap any character again to add more`;
            }
        }
        if(typeof window._updateAll === 'function') window._updateAll();
        showToast('🎭 Character topper removed', 1800);
    });
    document.getElementById('characterMovePanelClose').addEventListener('click', hidePanel);

    window._showCharacterMovePanel = showPanel;
    window._hideCharacterMovePanel = hidePanel;
})();
window.addEventListener('resize', () => {
    const w = container.clientWidth, h = container.clientHeight;
    renderer.setSize(w, h);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
});

// Fix compressed cake: re-sync size after full layout paint
requestAnimationFrame(() => requestAnimationFrame(() => {
    const w = container.clientWidth, h = container.clientHeight;
    renderer.setSize(w, h);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
}));

window._dumpScene = function(){
    console.log('=== FULL SCENE DUMP ===');
    scene.updateMatrixWorld(true);
    scene.traverse(obj=>{
        if(!obj.isMesh && !obj.isGroup) return;
        const box = new THREE.Box3().setFromObject(obj);
        const size = box.getSize(new THREE.Vector3());
        if(size.y > 1.0 || Math.max(size.x,size.z) > 1.0){
            console.log(obj.isMesh ? 'MESH' : 'GROUP', `"${obj.name || '(unnamed)'}"`,
                'size:', {x:+size.x.toFixed(3), y:+size.y.toFixed(3), z:+size.z.toFixed(3)},
                'parent:', obj.parent ? (obj.parent.name || obj.parent.type) : 'none',
                obj);
        }
    });
    console.log('=== END DUMP ===');
};
</script>

<script>
const TIER_INDEX = {'Single':0,'Two-tier':1,'Three-tier':2};
function getTierIdx(){ return TIER_INDEX[state.tier] ?? 0; }
// Hide options the admin deactivated
const DISABLED = @json($disabledNames ?? []);
// Admin name -> name used inside the builder
const NAME_ALIAS = {
    'Shell Border': 'Smooth Buttercream',
    'Fondant': 'Fondant Smooth',
    'Semi-naked': 'Semi-naked Style',
    'Ombre': 'Ombre Style',
    'Textured': 'Textured Buttercream',
    'Add Drip': 'Drip',
    'Cylinder Mix': 'Cylinder Sprinkles',
    'Pearl Mix': 'Sphere Sprinkles',
    'Ferrero': 'Ferrero-style Ball',
    'KitKat': 'Kitkat Sticks',
    'Oreo': 'Oreo Cookie',
    'Bar Shard': 'Chocolate Bar Shard',
    'Toblerone': 'Toblerone Triangle',
    'Mango Cube': 'Mango Slice'
};
const DISABLED_SET = new Set(DISABLED.map(n => NAME_ALIAS[n] || n));
document.querySelectorAll('[data-val]').forEach(el => {
    if (DISABLED_SET.has(el.dataset.val)) el.style.display = 'none';
});

// Coming Soon: visible, badged, not selectable
const COMING_SOON     = @json($comingSoonNames ?? []);
const COMING_SOON_SET = new Set(COMING_SOON.map(n => NAME_ALIAS[n] || n));
function isComingSoon(name){ return COMING_SOON_SET.has(name); }

document.querySelectorAll('[data-val],[data-cake-type],[data-filling]').forEach(el => {
    const name = el.dataset.val || el.dataset.cakeType || el.dataset.filling;
    if (!isComingSoon(name)) return;
    el.classList.add('is-coming-soon');
    el.classList.remove('active');
    el.setAttribute('aria-disabled', 'true');
    el.title = 'Coming Soon';
    el.insertAdjacentHTML('beforeend', '<span class="soon-badge">Coming Soon</span>');
});

// Capture phase runs before every existing click handler, so none of them fire
document.addEventListener('click', e => {
    if (e.target.closest('.is-coming-soon')) { e.preventDefault(); e.stopPropagation(); }
}, true);

// Coming Soon components the builder has no tile for yet (added in admin) → add a locked tile
@php
    $soonItems = $components->flatten(1)->where('status', 'coming_soon')
        ->map(fn($c) => ['category' => $c->category, 'name' => $c->name, 'emoji' => $c->emoji])
        ->values();
@endphp
const SOON_ITEMS = @json($soonItems);
const SOON_CONTAINERS = {
    cake_style: () => document.getElementById('opts-cake-style'),
    base_icing: () => document.getElementById('opts-frosting-base'),
    texture:    () => document.getElementById('opts-frosting-special'),
    drip:       () => document.getElementById('dripToggleBtn')?.parentElement,
    sprinkle:   () => document.getElementById('opts-sprinkles'),
    fruit:      () => document.getElementById('opts-fruits'),
    choco:      () => document.getElementById('opts-choco'),
};
const soonEsc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

SOON_ITEMS.forEach(item => {
    const getBox = SOON_CONTAINERS[item.category];
    const box = getBox && getBox();
    if (!box) return;

    // Skip if the builder already has a tile for it (the marking code above handles those)
    const key = NAME_ALIAS[item.name] || item.name;
    const exists = Array.from(box.querySelectorAll('[data-val]'))
        .some(el => el.dataset.val === key || el.dataset.val === item.name);
    if (exists) return;

    const vertical = item.category === 'fruit' || item.category === 'choco';
    const tile = document.createElement('div');
    tile.className = 'addon-opt is-coming-soon';
    tile.dataset.soon = item.name;          // not data-val, so no builder logic touches it
    tile.setAttribute('aria-disabled', 'true');
    tile.title = 'Coming Soon';
    if (vertical) tile.style.cssText = 'flex-direction:column;align-items:center;padding:10px 6px;gap:6px;border-radius:12px;';
    tile.innerHTML =
        '<div class="a-icon">' + soonEsc(item.emoji || '✨') + '</div>' +
        '<div class="a-info"><span class="a-name">' + soonEsc(item.name) + '</span></div>' +
        '<span class="soon-badge">Coming Soon</span>';
    box.appendChild(tile);
});
const CAKE_STYLE_DB   = @json($tierPriceMaps['cake_style']);
const BASE_ICING_DB   = @json($tierPriceMaps['base_icing']);
const TEXTURE_DB      = @json($tierPriceMaps['texture']);
const DRIP_DB         = @json($tierPriceMaps['drip']);
const SPRINKLE_DB     = @json($tierPriceMaps['sprinkle']);
const CHOCO_TIERED_DB = @json($tierPriceMaps['choco']);

const CAKE_STYLE_TIER_PRICES = Object.assign({
    'Smooth Buttercream': [0,250,450],
    'Semi-naked Style':   [200,400,600],
    'Fondant Smooth':     [350,750,1100],
    'Ombre Style':        [250,500,750],
}, CAKE_STYLE_DB);

// DB names this section, but the code refers to the same option as 'Smooth Buttercream'
// (it's both the default cake style AND the Shell Border overlay toggle).
const FROSTING_SHELL_TIER_PRICES   = BASE_ICING_DB['Shell Border'] || [0,100,180];
const FROSTING_SUGAR_TIER_PRICES   = BASE_ICING_DB['Sugar Icing']  || [150,300,450];
const FROSTING_ROSETTE_TIER_PRICES = BASE_ICING_DB['Rosettes']     || [100,300,500];
const FROSTING_TEXTURE_TIER_PRICES = TEXTURE_DB['Textured Buttercream'] || [150,300,450];

const ADDON_TIER_PRICES = {
    'Drip':                DRIP_DB['Drip'] || [180,300,450],
    'Cylinder Sprinkles':  SPRINKLE_DB['Cylinder Sprinkles'] || [30,50,70],
    'Sphere Sprinkles':    SPRINKLE_DB['Sphere Sprinkles']   || [30,50,70],
    'Chocolate Curls':     CHOCO_TIERED_DB['Chocolate Curls']     || [45,80,120],
    'Chocolate Sprinkles': CHOCO_TIERED_DB['Chocolate Sprinkles'] || [30,50,75],
    'Crushed Peanuts':     CHOCO_TIERED_DB['Crushed Peanuts']     || [35,60,90],
};
const CHOCO_PIECE_PRICES = Object.assign({'Ferrero-style Ball':55,'Kitkat Sticks':30,'Oreo Cookie':20,'Chocolate Bar Shard':40,'Toblerone Triangle':50},@json($priceMaps['choco']));
const CANDLE_PRICE_MAP = @json($priceMaps['candle']);
const CANDLE_PIECE_PRICE = CANDLE_PRICE_MAP['Number Candles'] || CANDLE_PRICE_MAP['Number Candles (0–9)'] || 20;
// Keeps every priced button's visible text AND data-price in sync with the
// currently selected tier, so click handlers that read dataset.price always
// pick up the right tier-adjusted amount.
function refreshTierPriceLabels(){
    const ti = getTierIdx();
    function setLabel(selector, price, opts){
        const el = document.querySelector(selector);
        if(!el) return;
        const span = el.classList.contains('a-price') ? el : el.querySelector('.a-price');
        if(!span) return;
        const suffix = '';
        span.textContent = price===0 ? `Default · Included${suffix}` : `+₱${price.toLocaleString()}${suffix}`;
        if(el.dataset) el.dataset.price = price;
    }

    setLabel('#opts-cake-style [data-val="Smooth Buttercream"]', CAKE_STYLE_TIER_PRICES['Smooth Buttercream'][ti]);
    setLabel('#opts-cake-style [data-val="Semi-naked Style"]',   CAKE_STYLE_TIER_PRICES['Semi-naked Style'][ti]);
    setLabel('#opts-cake-style [data-val="Fondant Smooth"]',     CAKE_STYLE_TIER_PRICES['Fondant Smooth'][ti]);
    setLabel('#opts-cake-style [data-val="Ombre Style"]',        CAKE_STYLE_TIER_PRICES['Ombre Style'][ti]);

    setLabel('#opts-frosting-base [data-val="Smooth Buttercream"]', FROSTING_SHELL_TIER_PRICES[ti], {suffix:'choose color'});
    setLabel('#opts-frosting-base [data-val="Sugar Icing"]',        FROSTING_SUGAR_TIER_PRICES[ti], {suffix:'choose color'});

    setLabel('#opts-frosting-special [data-val="Textured Buttercream"]', FROSTING_TEXTURE_TIER_PRICES[ti], {suffix:'add-on'});
    setLabel('#opts-frosting-special [data-val="Rosettes"]',             FROSTING_ROSETTE_TIER_PRICES[ti], {suffix:'add-on'});

    setLabel('#dripToggleBtn', ADDON_TIER_PRICES['Drip'][ti], {suffix:'pick flavor'});

    setLabel('#opts-sprinkles [data-val="Cylinder Sprinkles"]', ADDON_TIER_PRICES['Cylinder Sprinkles'][ti]);
    setLabel('#opts-sprinkles [data-val="Sphere Sprinkles"]',   ADDON_TIER_PRICES['Sphere Sprinkles'][ti]);

    setLabel('#opts-choco [data-val="Chocolate Curls"]',     ADDON_TIER_PRICES['Chocolate Curls'][ti],     {suffix:'add-on'});
    setLabel('#opts-choco [data-val="Chocolate Sprinkles"]', ADDON_TIER_PRICES['Chocolate Sprinkles'][ti]);
    setLabel('#opts-choco [data-val="Crushed Peanuts"]',     ADDON_TIER_PRICES['Crushed Peanuts'][ti]);

    // Any of these add-ons already active on the cake get their stored price
    // bumped/dropped immediately too, so the total reflects the new tier
    // even without the customer re-clicking the button.
    Object.keys(ADDON_TIER_PRICES).forEach(k=>{
        if(state.addons.has(k)) state.addons.set(k, ADDON_TIER_PRICES[k][ti]);
    });
}
function tierCountFor(tier){ return tier==='Three-tier'?3:tier==='Two-tier'?2:1; }
const CAKE_SIZE_CATEGORIES = [
    {min:4,max:5,name:'Bento Cake',desc:'A cute personal-sized treat'},
    {min:6,max:6,name:'Small Cake',desc:'Perfect for small celebrations'},
    {min:7,max:8,name:'Regular Cake',desc:'Great for standard celebrations'},
    {min:9,max:10,name:'Large Cake',desc:'Ideal for bigger gatherings'},
];
function getCakeSizeCategory(size){
    return CAKE_SIZE_CATEGORIES.find(c=>size>=c.min&&size<=c.max) || CAKE_SIZE_CATEGORIES[CAKE_SIZE_CATEGORIES.length-1];
}
function updateSizeLabelBadge(){
    const cat = getCakeSizeCategory(state.roundSize);
    const nameEl = document.getElementById('sizeCategoryName');
    const rangeEl = document.getElementById('sizeCategoryRange');
    const descEl = document.getElementById('sizeCategoryDesc');
    if(nameEl) nameEl.textContent = cat.name;
    if(rangeEl) rangeEl.textContent = `${cat.min}"–${cat.max}"`;
    if(descEl) descEl.textContent = cat.desc;
}
function syncSizeSliderVisibility(){
    const isResizableShape = (state.shape==='Round'||state.shape==='Square'||state.shape==='Heart');
    const showSize = isResizableShape && state.tier==='Single';
    // Cake Height now follows the same restriction as Round Size — Number and
    // Bundt cakes keep a fixed, non-adjustable height (previously this only
    // checked tier, so the Height slider stayed visible/usable for those
    // shapes even though resizing isn't supported for them).
    const showHeight = isResizableShape && state.tier==='Single';
    document.getElementById('sizeSliderWrap').classList.toggle('visible', showSize);
    document.getElementById('heightSliderWrap').classList.toggle('visible', showHeight);
    if(!showHeight && state.heightMult !== 1.0){
        // Reset to the default 100% height whenever the slider is hidden —
        // this now covers Number/Bundt cakes AND Two-tier/Three-tier
        // Round/Square/Heart, so a tiered cake always renders at its fixed
        // default height instead of inheriting a custom height left over
        // from Single-tier mode.
        state.heightMult = 1.0;
        const heightRangeEl = document.getElementById('heightRange');
        const heightDisplayEl = document.getElementById('heightDisplay');
        if(heightRangeEl) heightRangeEl.value = 100;
        if(heightDisplayEl) heightDisplayEl.textContent = 100;
    }
    if(!showSize && state.roundSize !== 6){
        // Same idea for size — Two-tier/Three-tier (and Number/Bundt) always
        // use their fixed default base size, never a leftover Round Size
        // value from Single-tier mode. This also fixes Square/Heart tiered
        // pricing, which was scaling off the stale state.roundSize.
        state.roundSize = 6;
        const sizeRangeEl = document.getElementById('sizeRange');
        const sizeDisplayEl = document.getElementById('sizeDisplay');
        if(sizeRangeEl) sizeRangeEl.value = 6;
        if(sizeDisplayEl) sizeDisplayEl.textContent = 6;
    }
    updateSizeLabelBadge();
}
const LAYER_LINE_LABEL = {1:'No lines',2:'1 line',3:'3 lines'};
function renderTierLayerRows(){
    const section = document.getElementById('cakeLayersSection');
    const wrap = document.getElementById('tierLayerRows');
    if(!wrap || !section) return;
    section.style.display = state.shape==='Bundt' ? 'none' : '';
    const count = tierCountFor(state.tier);
    while(state.tierLayers.length < 3) state.tierLayers.push(1);
    while(state.tierFlavors.length < 3) state.tierFlavors.push(state.flavor);
    while(state.tierFrostings.length < 3) state.tierFrostings.push(state.flavor);
    while(state.tierFillings.length < 3) state.tierFillings.push('No Filling');
    const labels = ['Tier 1 (bottom)','Tier 2 (middle)','Tier 3 (top)'];
    const flavorNames = FLAVOR_NAMES;
    const fillingNames = Array.from(document.querySelectorAll('#opts-filling [data-filling]')).map(el => el.dataset.filling);
    wrap.innerHTML = '';

    const ICONS = {
        base: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 21 L12 3 L21 21 Z"/><line x1="7.5" y1="12" x2="16.5" y2="12"/></svg>',
        frosting: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-8a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8"/><path d="M4 21h16"/><path d="M12 3v6"/><path d="M8 11c0-2 1-3 4-3s4 1 4 3"/></svg>',
        filling: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="3" rx="1"/><path d="M4 8c0-2 2-3 4-3h8c2 0 4 1 4 3"/><path d="M4 17c0 2 2 3 4 3h8c2 0 4-1 4-3"/></svg>',
        lock: '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;margin-right:4px;"><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>',
    };

    function makeFieldRow(iconSvg, labelText, options, currentVal, onChange){
        const field = document.createElement('div');
        field.style.cssText = 'display:flex;flex-direction:column;gap:7px;';
        const lblRow = document.createElement('div');
        lblRow.style.cssText = 'display:flex;align-items:center;gap:7px;color:var(--brown-mid);';
        lblRow.innerHTML = `<span style="display:flex;align-items:center;flex-shrink:0;">${iconSvg}</span><span style="font-size:.70rem;font-weight:700;color:var(--brown-mid);font-family:var(--font-display);text-transform:uppercase;letter-spacing:.05em;">${labelText}</span>`;
        field.appendChild(lblRow);
        const select = document.createElement('select');
        select.style.cssText = 'width:100%;padding:11px 13px;border:1.5px solid var(--border-dk);border-radius:10px;background:var(--surface);color:var(--text);font-size:.80rem;font-weight:600;font-family:var(--font-display);cursor:pointer;transition:border-color .15s,box-shadow .15s;';
        select.addEventListener('mouseenter', ()=>{ select.style.borderColor='var(--caramel)'; });
        select.addEventListener('mouseleave', ()=>{ select.style.borderColor='var(--border-dk)'; });
        select.addEventListener('focus', ()=>{ select.style.boxShadow='0 0 0 3px rgba(200,137,74,.18)'; });
        select.addEventListener('blur', ()=>{ select.style.boxShadow=''; });
        options.forEach(name=>{
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = name;
            if (isComingSoon(name)) { opt.disabled = true; opt.textContent = name + ' (Coming Soon)'; }
            if(currentVal === name) opt.selected = true;
            select.appendChild(opt);
        });
        select.addEventListener('change', ()=> onChange(select.value));
        field.appendChild(select);
        return field;
    }

    for(let i=0;i<count;i++){
        const row = document.createElement('div');
        row.style.cssText = 'display:flex;flex-direction:column;gap:18px;background:var(--warm-white);border:1.5px solid var(--border-dk);border-radius:16px;padding:18px 18px 20px;box-shadow:var(--shadow-xs);';

        const topRow = document.createElement('div');
        topRow.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:14px;border-bottom:1px dashed var(--border);';
        const lbl = document.createElement('span');
        lbl.style.cssText = 'font-size:.90rem;font-weight:800;color:var(--brown-deep);font-family:var(--font-display);letter-spacing:-0.01em;';
        lbl.textContent = labels[i];
        topRow.appendChild(lbl);
        const btnGroup = document.createElement('div');
        btnGroup.style.cssText = 'display:flex;gap:6px;';
        [1,2,3].forEach(n=>{
            const b = document.createElement('button');
            b.type = 'button';
            b.textContent = n+(n>1?' layers':' layer');
            const active = (state.tierLayers[i]||1) === n;
            b.style.cssText = `padding:8px 13px;border-radius:10px;border:1.5px solid ${active?'var(--caramel)':'var(--border)'};background:${active?'var(--caramel)':'var(--surface)'};color:${active?'#fff':'var(--text-muted)'};font-size:.72rem;font-weight:700;cursor:pointer;font-family:var(--font-display);transition:all .15s;`;
            b.title = LAYER_LINE_LABEL[n];
            b.addEventListener('click',()=>{
                state.tierLayers[i]=n;
                if(n>1 && (!state.tierFillings[i] || state.tierFillings[i]==='No Filling')){
                    state.tierFillings[i]='Chocolate';
                    if(i===0) state.filling='Chocolate';
                }
                renderTierLayerRows();
                updateAll();
            });
            btnGroup.appendChild(b);
        });
        topRow.appendChild(btnGroup);
        row.appendChild(topRow);

        const fieldsWrap = document.createElement('div');
        fieldsWrap.style.cssText = 'display:flex;flex-direction:column;gap:16px;';

        // Base Cake Flavour — colors the INSIDE crumb (only visible when sliced)
        fieldsWrap.appendChild(makeFieldRow(ICONS.base, 'Cake Flavor', flavorNames, state.tierFlavors[i]||state.flavor, (val)=>{
            state.tierFlavors[i] = val;
            if(i===0) state.innerFlavor = val;
            updateAll();
        }));

        // Filling — the line(s) BETWEEN this tier's own layers
        const fillingField = makeFieldRow(ICONS.filling, 'Filling', fillingNames, state.tierFillings[i]||'No Filling', (val)=>{
            state.tierFillings[i] = val;
            if(i===0) state.filling = val;
            updateAll();
        });
        const hasMultiLayer = (state.tierLayers[i]||1) > 1;
        fillingField.style.opacity = hasMultiLayer ? '1' : '0.42';
        fillingField.style.pointerEvents = hasMultiLayer ? '' : 'none';
        if(!hasMultiLayer && state.tierFillings[i] !== 'No Filling') state.tierFillings[i] = 'No Filling';
        fieldsWrap.appendChild(fillingField);
        if(!hasMultiLayer){
            const hint = document.createElement('div');
            hint.style.cssText = 'font-size:.66rem;color:var(--text-muted);font-family:var(--font-display);margin-top:-8px;display:flex;align-items:center;';
            hint.innerHTML = ICONS.lock + 'Add a 2nd layer to choose a filling';
            fieldsWrap.appendChild(hint);
        }

        // Frosting — colors the OUTSIDE of this tier
        fieldsWrap.appendChild(makeFieldRow(ICONS.frosting, 'Frosting Flavor', flavorNames, state.tierFrostings[i]||state.flavor, (val)=>{
            state.tierFrostings[i] = val;
            if(i===0) state.flavor = val; // keep tier 1 in sync with the rest of the app
            updateAll();
        }));

        row.appendChild(fieldsWrap);
        wrap.appendChild(row);
    }

    const fillingSection = document.getElementById('fillingSection');
    if(fillingSection) fillingSection.style.display = 'none';
}

const TIER_FRUIT_BORDER_OPTIONS = ['None','Mango Slice','Kiwi Slice','Peach Slice','Banana Slice'];
function renderTierFruitBorderRows(){
    const section = document.getElementById('tierFruitBorderSection');
    const wrap = document.getElementById('tierFruitBorderRows');
    if(!section || !wrap) return;
    const isTiered = state.tier !== 'Single';
    section.style.display = isTiered ? '' : 'none';
    if(!isTiered) return;

    while(state.tierFruitBorders.length < 3) state.tierFruitBorders.push('None');
    const count = tierCountFor(state.tier);
    const labels = ['Tier 1 (bottom)','Tier 2 (middle)','Tier 3 (top)'];
    wrap.innerHTML = '';
    for(let i=0;i<count;i++){
        const row = document.createElement('div');
        row.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:10px;';
        const lbl = document.createElement('span');
        lbl.style.cssText = 'font-size:.72rem;font-weight:700;color:var(--brown-mid);font-family:var(--font-display);flex-shrink:0;';
        lbl.textContent = labels[i];
        row.appendChild(lbl);

        const select = document.createElement('select');
        select.style.cssText = 'flex:1;padding:8px 10px;border:1.5px solid var(--border-dk);border-radius:9px;background:var(--surface);color:var(--text);font-size:.74rem;font-weight:600;font-family:var(--font-display);cursor:pointer;';
        TIER_FRUIT_BORDER_OPTIONS.forEach(name=>{
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = name === 'None' ? 'No fruit border' : (GRAM_FRUIT_LABELS[name] || name);
            if((state.tierFruitBorders[i]||'None') === name) opt.selected = true;
            select.appendChild(opt);
        });
        select.addEventListener('change', ()=>{
            state.tierFruitBorders[i] = select.value;
            if(typeof window.buildTierFruitBorder==='function'){
                window.buildTierFruitBorder(i, select.value === 'None' ? null : select.value);
            }
            updateAll();
        });
        row.appendChild(select);
        wrap.appendChild(row);
    }
}

