        addonTotal += ADDON_TIER_PRICES[k] ? ADDON_TIER_PRICES[k][ti] : p;
    });
 const FRUIT_PRICES=Object.assign({'Strawberry':45,'Blueberry':25,'Raspberry':55,'Cherry':35,'Leaf':50},@json($priceMaps['fruit']));
