if(state.addons.has('Ferrero-style Ball'))addonTotal+=ferreroCount*(CHOCO_PIECE_PRICES['Ferrero-style Ball']||55);
    if(state.addons.has('Kitkat Sticks'))addonTotal+=kitkatCount*(CHOCO_PIECE_PRICES['Kitkat Sticks']||30);
