    if(typeof window._reapplyAllHalfViews==='function') window._reapplyAllHalfViews();
    setTimeout(()=>{ if(typeof window._reapplyAllHalfViews==='function') window._reapplyAllHalfViews(); }, 2600);
}
// Gathers every placed decoration as CAKE-RELATIVE FRACTIONS (not screen
// pixels), so a draft can be rebuilt later at any camera angle/screen size —
// same fraction system already used by placeFruitAtFraction / preset loading.
function collectDecorPlacements(){
    if(typeof window._saveAllToppingNormals==='function') window._saveAllToppingNormals();
    const deg=r=>Math.round((r*180/Math.PI+360)%360);
    const out={};

    const fruits=(typeof window.getFruitModels==='function')?window.getFruitModels():[];
    out.fruits=fruits.filter(m=>m._normX!==undefined).map(m=>({
        fruit:m.fruit, x:m._normX, z:m._normZ,
        rotZ:deg(m.group.rotation.z), rotY:deg(m.group.rotation.y),
    }));

    const ferreros=(typeof window.getFerreroModels==='function')?window.getFerreroModels():[];
    out.ferrero=ferreros.filter(m=>m._normX!==undefined).map(m=>({
        x:m._normX, z:m._normZ, rotZ:deg(m.group.rotation.z), rotY:deg(m.group.rotation.y),
    }));

    const kitkats=(typeof window.getKitkatModels==='function')?window.getKitkatModels():[];
    out.kitkat=kitkats.filter(m=>m._normX!==undefined).map(m=>({
        x:m._normX, z:m._normZ, orientation:m.orientation,
    }));

    const oreos=(typeof window.getOreoModels==='function')?window.getOreoModels():[];
    out.oreo=oreos.filter(m=>m._normX!==undefined).map(m=>({
        x:m._normX, z:m._normZ, orientation:m.orientation,
    }));

    const barShards=(typeof window.getBarShardModels==='function')?window.getBarShardModels():[];
    out.barShard=barShards.filter(m=>m._normX!==undefined).map(m=>({
        x:m._normX, z:m._normZ, rotZ:deg(m.group.rotation.z), rotY:deg(m.group.rotation.y),
    }));

    const toblerones=(typeof window.getTobleroneModels==='function')?window.getTobleroneModels():[];
    out.toblerone=toblerones.filter(m=>m._normX!==undefined).map(m=>({
        x:m._normX, z:m._normZ, flavor:m.flavor, rotZ:deg(m.group.rotation.z), rotY:deg(m.group.rotation.y),
    }));

    const candles=(typeof window.getCandleModels==='function')?window.getCandleModels():[];
    out.candles=candles.filter(m=>m._normX!==undefined).map(m=>({
        x:m._normX, z:m._normZ, num:m.candleNum,
    }));

    const characters=(typeof window.getCharacterModels==='function')?window.getCharacterModels():[];
    out.characters=characters.filter(m=>m._normX!==undefined).map(m=>({
        x:m._normX, z:m._normZ, key:m.key, rotY:deg(m.group.rotation.y), size:m.sizeInches||4,
    }));

    return out;
}
// The complete, rebuildable cake config (used by Save Draft AND by submitted orders).
function buildDraftConfig(){
    return {
        cakeType:state.cakeType, filling:state.filling, shape:state.shape, tier:state.tier, roundSize:state.roundSize,
        heightMult:state.heightMult,
        numberDigits:state.numberDigits, numberChoice:state.numberChoice, numberTens:state.numberTens, numberUnits:state.numberUnits,
        flavor:state.flavor, frostings:[...state.frostings], addons:[...state.addons.keys()],
        hasDrip:state.hasDrip, dripFlavor:state.dripFlavor,
        icingColor:state.icingColor, icingColorName:state.icingColorName, hasCustomIcingColor:state.hasCustomIcingColor,
        shellBorderColor:state.shellBorderColor, shellBorderColorName:state.shellBorderColorName,
        decorations:collectDecorPlacements(),
        tierDecor:state.tierDecor,
        fruitGrams:{...state.fruitGrams},
        gramFruitPlacement:{...(window._gramFruitPlacement||{})},
        allFruitsAssorted:!!state.allFruitsAssorted,
        tierLayers:state.tierLayers.slice(0,3), tierFlavors:state.tierFlavors.slice(0,3),
        tierFrostings:state.tierFrostings.slice(0,3), tierFillings:state.tierFillings.slice(0,3),
        tierFruitBorders:state.tierFruitBorders.slice(0,3),
        halfView:{...state.halfView},
        shellBorderScale:state.shellBorderScale, icingScale:state.icingScale,
        rosetteBorderScale:state.rosetteBorderScale, chocoCurlsSidesScale:state.chocoCurlsSidesScale,
        fruitBorderScale:{...state.fruitBorderScale},
        kitkatOrientation:state.kitkatOrientation, oreoOrientation:state.oreoOrientation,
        chocoCurlsPlacement: state.addons.has('Chocolate Curls') ? state.chocoCurlsPlacement : null,
        plaqueShape: state.addons.has('Chocolate Plaque') ? state.plaqueShape : null,
        plaqueMessage: state.addons.has('Chocolate Plaque') ? state.plaqueMessage : '',
        rosettePlacement: state.frostings.has('Rosettes') ? state.rosettePlacement : null,
        rosetteColor: state.frostings.has('Rosettes') ? state.rosetteColor : null,
        rosetteColorName: state.frostings.has('Rosettes') ? state.rosetteColorName : null,
        ombreTopColor: state.frostings.has('Ombre Style') ? state.ombreTopColor : null,
        ombreBottomColor: state.frostings.has('Ombre Style') ? state.ombreBottomColor : null,
        sprinklePlacement: window._sprinklePlacement ? {...window._sprinklePlacement} : null,
        tobleroneFlavor:state.tobleroneFlavor, characterTopper:state.characterTopper,
        shapeLabel:getShapeLabel(), cakeLabel:getCombinedCakeTypeLabel(),
        total: parseInt((document.getElementById('priceTotal').textContent||'0').replace(/,/g,''))||0,
    };
}
async function saveDraft(){
    const cfg={
        cakeType:state.cakeType,filling:state.filling,shape:state.shape,tier:state.tier,roundSize:state.roundSize,
        numberDigits:state.numberDigits,numberChoice:state.numberChoice,numberTens:state.numberTens,numberUnits:state.numberUnits,
        flavor:state.flavor,frostings:[...state.frostings],addons:[...state.addons.keys()],
        hasDrip:state.hasDrip,dripFlavor:state.dripFlavor,icingColor:state.icingColor,icingColorName:state.icingColorName,
        hasCustomIcingColor:state.hasCustomIcingColor,
        shellBorderColor:state.shellBorderColor,shellBorderColorName:state.shellBorderColorName,
        decorations:collectDecorPlacements(),
        tierDecor:state.tierDecor,
        fruitGrams:{...state.fruitGrams},
        kitkatOrientation:state.kitkatOrientation,
        oreoOrientation:state.oreoOrientation,
        chocoCurlsPlacement: state.addons.has('Chocolate Curls') ? state.chocoCurlsPlacement : null,
        plaqueShape: state.addons.has('Chocolate Plaque') ? state.plaqueShape : null,
        plaqueMessage: state.addons.has('Chocolate Plaque') ? state.plaqueMessage : '',
        rosettePlacement: state.frostings.has('Rosettes') ? state.rosettePlacement : null,
        rosetteColor: state.frostings.has('Rosettes') ? state.rosetteColor : null,
        rosetteColorName: state.frostings.has('Rosettes') ? state.rosetteColorName : null,
        ombreTopColor: state.frostings.has('Ombre Style') ? state.ombreTopColor : null,
        ombreBottomColor: state.frostings.has('Ombre Style') ? state.ombreBottomColor : null,
        sprinklePlacement: window._sprinklePlacement ? {...window._sprinklePlacement} : null,
        tobleroneFlavor: state.tobleroneFlavor,
        characterTopper: state.characterTopper,
        shapeLabel:getShapeLabel(),
        cakeLabel:getCombinedCakeTypeLabel(),
        total: parseInt((document.getElementById('priceTotal').textContent||'0').replace(/,/g,''))||0,
    };
    Object.assign(cfg, buildDraftConfig());
    document.getElementById('saveDraftConfigInput').value = JSON.stringify(cfg);

    // Capture a transparent PNG of the cake exactly as it looks right now,
    // using the same beauty-shot angle proceed() uses for order snapshots.
    const canvas = document.querySelector('#model-container canvas');
    if (canvas && window._threeCamera && window._threeControls && window._threeRenderer && window._threeScene) {
        const _cam = window._threeCamera, _ctl = window._threeControls, _ren = window._threeRenderer, _scn = window._threeScene;
        const savedPos = _cam.position.clone(), savedTarget = _ctl.target.clone();
        const tier = state ? state.tier : 'Single';
        let camY = 0.8, camZ = 7.0, tgtY = -0.6;
        if (tier === 'Two-tier')   { camY = 1.2; camZ = 8.5;  tgtY = -0.2; }
        if (tier === 'Three-tier') { camY = 1.8; camZ = 10.5; tgtY = 0.2; }
          _cam.position.set(0, camY, camZ);
        _ctl.target.set(0, tgtY, 0);
        _ctl.update();

           const _hiddenForSnapshot = [];
        _scn.traverse(obj => {
            if (obj.userData && (obj.userData.isBackgroundProp || obj.userData.isStand) && obj.visible) {
                _hiddenForSnapshot.push(obj);
                obj.visible = false;
            }
        });
        _ren.render(_scn, _cam);
        try {
            const off = document.createElement('canvas');
            off.width = canvas.width;
            off.height = canvas.height;
            const ctx = off.getContext('2d');
            ctx.drawImage(canvas, 0, 0); // no fill = stays transparent

            // Auto-crop to the visible (non-transparent) cake pixels so the
            // saved thumbnail is tightly framed instead of mostly empty space.
            const imgData = ctx.getImageData(0, 0, off.width, off.height);
            const data = imgData.data;
            let minX = off.width, minY = off.height, maxX = 0, maxY = 0;
            const ALPHA_THRESHOLD = 10;
            for (let y = 0; y < off.height; y += 2) {
                for (let x = 0; x < off.width; x += 2) {
                    const alpha = data[(y * off.width + x) * 4 + 3];
                    if (alpha > ALPHA_THRESHOLD) {
                        if (x < minX) minX = x;
                        if (x > maxX) maxX = x;
                        if (y < minY) minY = y;
                        if (y > maxY) maxY = y;
                    }
                }
            }

            if (maxX > minX && maxY > minY) {
                const pad = Math.round(Math.max(maxX - minX, maxY - minY) * 0.08);
                minX = Math.max(0, minX - pad);
                minY = Math.max(0, minY - pad);
                maxX = Math.min(off.width, maxX + pad);
                maxY = Math.min(off.height, maxY + pad);
                const cropW = maxX - minX;
                const cropH = maxY - minY;

                const cropped = document.createElement('canvas');
                cropped.width = cropW;
                cropped.height = cropH;
                cropped.getContext('2d').drawImage(off, minX, minY, cropW, cropH, 0, 0, cropW, cropH);
                document.getElementById('saveDraftPreviewInput').value = cropped.toDataURL('image/png');
            } else {
                document.getElementById('saveDraftPreviewInput').value = off.toDataURL('image/png');
            }
        } catch(e) {
            console.warn('Draft snapshot failed:', e);
        }

        // Restore background props for the normal builder view
        _hiddenForSnapshot.forEach(obj => { obj.visible = true; });
        if (typeof window._requestRender === 'function') window._requestRender(500);

        _cam.position.copy(savedPos);
        _ctl.target.copy(savedTarget);
        _ctl.update();
    }

    document.getElementById('saveDraftForm').submit();
}
if(document.getElementById('btnSaveDraft')) document.getElementById('btnSaveDraft').addEventListener('click',saveDraft);

// ── LOAD DRAFT ── (pass an id to resume a specific saved draft)
async function fetchDraftById(id){
    const url = id
        ? '{{ route("customer.cake-builder.loadDraft") }}?id=' + encodeURIComponent(id)
        : '{{ route("customer.cake-builder.loadDraft") }}';
    const res = await fetch(url);
    const data = await res.json();
    return data.draft;
}

// Restores a saved draft's ENTIRE cake — shape/flavor/frosting/tier AND every
// placed decoration (fruits, chocolates, candles, characters) at its saved
// cake-relative position. Used by both "Load Saved Draft" / "Resume Editing"
// inside the builder, and by the read-only preview mode on the drafts gallery.
async function applyDraftConfig(d){
    if(!d) return;

    if(typeof window.clearFruitModels==='function')     window.clearFruitModels();
    if(typeof window.clearFerreroModels==='function')   window.clearFerreroModels();
    if(typeof window.clearKitkatModels==='function')    window.clearKitkatModels();
    if(typeof window.clearOreoModels==='function')      window.clearOreoModels();
    if(typeof window.clearBarShardModels==='function')  window.clearBarShardModels();
    if(typeof window.clearTobleroneModels==='function') window.clearTobleroneModels();
    if(typeof window.clearCandleModels==='function')    window.clearCandleModels();
    if(typeof window.clearCharacterModels==='function') window.clearCharacterModels();
    if(typeof window.clearChocoCurls==='function')      window.clearChocoCurls();
    if(typeof window.clearPlaque==='function')          window.clearPlaque();
    state.addons = new Map();

    document.getElementById('opts-shape').querySelectorAll('[data-val]').forEach(el=>el.classList.toggle('active',el.dataset.val===d.shape));
    state.shape=d.shape||'Round';
    if(d.roundSize){state.roundSize=d.roundSize;document.getElementById('sizeRange').value=state.roundSize;document.getElementById('sizeDisplay').textContent=state.roundSize;}
    document.getElementById('numberPickerWrap').classList.toggle('visible',state.shape==='Number');
    if(d.tier){
        state.tier = d.tier;
        document.getElementById('opts-tier').querySelectorAll('[data-tier]').forEach(el=>el.classList.toggle('active', el.dataset.tier===d.tier));
    }
    document.getElementById('cakeTierSection').style.display = (state.shape === 'Round' || state.shape === 'Square' || state.shape === 'Heart') ? '' : 'none';
    syncSizeSliderVisibility();

    if(state.shape==='Number'){
        const digits=d.numberDigits||1;state.numberDigits=digits;const isSingle=digits===1;
        document.getElementById('btnSingleDigit').classList.toggle('active',isSingle);document.getElementById('btnDualDigit').classList.toggle('active',!isSingle);
        document.getElementById('singleDigitSection').style.display=isSingle?'':'none';document.getElementById('dualDigitSection').classList.toggle('visible',!isSingle);
        if(isSingle&&d.numberChoice!==undefined){state.numberChoice=d.numberChoice;document.getElementById('opts-number').querySelectorAll('.num-opt').forEach(el=>el.classList.toggle('active',parseInt(el.dataset.val)===state.numberChoice));}
        else if(!isSingle){state.numberTens=d.numberTens??1;state.numberUnits=d.numberUnits??0;document.getElementById('opts-tens').querySelectorAll('.num-opt-sm').forEach(el=>el.classList.toggle('active',parseInt(el.dataset.val)===state.numberTens));document.getElementById('opts-units').querySelectorAll('.num-opt-sm').forEach(el=>el.classList.toggle('active',parseInt(el.dataset.val)===state.numberUnits));refreshDualPreview();}
    }
    if(d.cakeType){state.cakeType=d.cakeType;document.getElementById('opts-cake-type').querySelectorAll('[data-cake-type]').forEach(el=>el.classList.toggle('active',el.dataset.cakeType===d.cakeType));syncCakeTypeUI();}
    if(d.filling){state.filling=d.filling;document.getElementById('opts-filling').querySelectorAll('[data-filling]').forEach(el=>el.classList.toggle('active',el.dataset.filling===d.filling));}
    state.flavor=d.flavor||'Vanilla';
    state.tierFlavors[0]=state.flavor;
    state.tierFrostings[0]=state.flavor;

    state.frostings=new Set();
    (Array.isArray(d.frostings)?d.frostings:(d.frosting?[d.frosting]:[])).forEach(f=>state.frostings.add(f));

    state.icingColor=d.icingColor||'#FFFFFF';
    state.icingColorName=d.icingColorName||'White';
    state.hasCustomIcingColor=!!d.hasCustomIcingColor;
    document.getElementById('icingColorGrid').querySelectorAll('.icing-color-opt').forEach(el=>el.classList.toggle('active',el.dataset.icingColor===state.icingColor));
    document.getElementById('icingColorLabel').textContent=state.icingColorName;
    state.shellBorderColor=d.shellBorderColor||'#FFFFFF';
    state.shellBorderColorName=d.shellBorderColorName||'White';
    document.getElementById('shellBorderColorGrid').querySelectorAll('.icing-color-opt').forEach(el=>el.classList.toggle('active',el.dataset.shellColor===state.shellBorderColor));
    document.getElementById('shellBorderColorLabel').textContent=state.shellBorderColorName;

    if(d.rosettePlacement){
        state.rosettePlacement = d.rosettePlacement;
        document.querySelectorAll('#opts-rosette-placement [data-rosette-placement], #opts-rosette-combo [data-rosette-placement]').forEach(el=>el.classList.toggle('active', el.dataset.rosettePlacement===d.rosettePlacement));
        const badge=document.getElementById('rosettePlacementBadge'); if(badge) badge.textContent='Selected: '+d.rosettePlacement.replace('+',' + ');
    }
    if(d.rosetteColor){
        state.rosetteColor = d.rosetteColor; state.rosetteColorName = d.rosetteColorName || d.rosetteColor;
        document.getElementById('rosetteColorGrid').querySelectorAll('.icing-color-opt').forEach(el=>el.classList.toggle('active', el.dataset.rosetteColor===d.rosetteColor));
        document.getElementById('rosetteColorLabel').textContent = state.rosetteColorName;
    }
    if(d.ombreTopColor) state.ombreTopColor = d.ombreTopColor;
    if(d.ombreBottomColor) state.ombreBottomColor = d.ombreBottomColor;
    updateOmbrePreview();

    syncFrostingUI();

    state.hasDrip=!!d.hasDrip;
    state.dripFlavor=d.dripFlavor||'Vanilla';
    document.getElementById('dripToggleBtn').classList.toggle('active',state.hasDrip);
    document.getElementById('dripFlavorPanel').classList.toggle('visible',state.hasDrip);
    document.getElementById('dripFlavorOpts').querySelectorAll('.drip-flavor-opt').forEach(el=>el.classList.toggle('active',el.dataset.dripFlavor===state.dripFlavor));
    if(state.hasDrip){ state.addons.set('Drip',180); window._pendingDripReveal = true; }

    state.kitkatOrientation = d.kitkatOrientation || 'standing';
    document.getElementById('btnKitkatStanding').classList.toggle('active',state.kitkatOrientation==='standing');
    document.getElementById('btnKitkatLying').classList.toggle('active',state.kitkatOrientation==='lying');
    document.getElementById('kitkatOrientBadge').textContent=state.kitkatOrientation==='standing'?'📏 Standing':'📐 Lying Flat';

    state.oreoOrientation = d.oreoOrientation || 'lying';
    document.getElementById('btnOreoStanding').classList.toggle('active',state.oreoOrientation==='standing');
    document.getElementById('btnOreoLying').classList.toggle('active',state.oreoOrientation==='lying');
    document.getElementById('oreoOrientBadge').textContent=state.oreoOrientation==='standing'?'🔘 Standing':'⚫ Lying Flat';

    state.tobleroneFlavor = d.tobleroneFlavor || 'Chocolate';

    // ── per-tier flavors, height, sizes, half views (previously not restored) ──
    if(typeof d.heightMult==='number' && d.heightMult>0){
        state.heightMult = d.heightMult;
        const hr=document.getElementById('heightRange'), hd=document.getElementById('heightDisplay');
        if(hr) hr.value = Math.round(d.heightMult*100);
        if(hd) hd.textContent = Math.round(d.heightMult*100);
    }
    const _pad3 = (arr,def)=>{ const a = Array.isArray(arr) ? arr.slice(0,3) : []; while(a.length<3) a.push(def); return a; };
    if(d.tierLayers)     state.tierLayers = _pad3(d.tierLayers,1);
    if(d.tierFlavors){   state.tierFlavors = _pad3(d.tierFlavors,state.flavor); state.innerFlavor = state.tierFlavors[0]; }
    if(d.tierFrostings){ state.tierFrostings = _pad3(d.tierFrostings,state.flavor); state.flavor = state.tierFrostings[0]; }
    if(d.tierFillings){  state.tierFillings = _pad3(d.tierFillings,'No Filling'); state.filling = state.tierFillings[0]; }
    if(d.tierFruitBorders) state.tierFruitBorders = _pad3(d.tierFruitBorders,'None');
    if(d.halfView) Object.assign(state.halfView, d.halfView);
    ['shellBorderScale','icingScale','rosetteBorderScale','chocoCurlsSidesScale'].forEach(k=>{ if(typeof d[k]==='number') state[k]=d[k]; });
    if(d.fruitBorderScale) Object.assign(state.fruitBorderScale, d.fruitBorderScale);
    state._manualRingScale = {shell:true, icing:true, rosette:true};
    state.allFruitsAssorted = !!d.allFruitsAssorted;
    if(d.gramFruitPlacement && window._gramFruitPlacement) Object.assign(window._gramFruitPlacement, d.gramFruitPlacement);
    renderTierLayerRows(); renderTierFruitBorderRows();
    if(d.tierDecor){ state.tierDecor = d.tierDecor; syncComboRingScales(); }
    state.fruitGrams = d.fruitGrams || {};
    Object.keys(state.fruitGrams).forEach(k=>{ if(!state.addons.has(k)) state.addons.set(k, 0); });
    if(typeof syncFruitGramUI==='function') syncFruitGramUI();
    state.characterTopper = d.characterTopper || state.characterTopper;

    const decor = d.decorations || {};
    if((decor.fruits||[]).length){ decor.fruits.forEach(f=>state.addons.set(f.fruit,0)); updateFruitTray(); }
    if((decor.ferrero||[]).length){ state.addons.set('Ferrero-style Ball',0); document.getElementById('ferreroToggleBtn').classList.add('active'); updateFerreroTray(); }
    if((decor.kitkat||[]).length){ state.addons.set('Kitkat Sticks',0); document.getElementById('kitkatToggleBtn').classList.add('active'); updateKitkatTray(); }
    if((decor.oreo||[]).length){ state.addons.set('Oreo Cookie',0); document.getElementById('oreoToggleBtn').classList.add('active'); updateOreoTray(); }
    if((decor.barShard||[]).length){ state.addons.set('Chocolate Bar Shard',0); document.querySelector('#opts-choco .addon-opt[data-val="Chocolate Bar Shard"]').classList.add('active'); updateBarShardTray(); }
    if((decor.toblerone||[]).length){ state.addons.set('Toblerone Triangle',0); document.getElementById('tobleroneToggleBtn').classList.add('active'); updateTobleroneTray(); }
    if((decor.candles||[]).length){ state.addons.set('Number Candles',0); document.getElementById('opts-candles').querySelector('[data-val="Number Candles"]').classList.add('active'); updateCandleTray(); }
    if((decor.characters||[]).length){ state.addons.set('Character Topper',0); document.getElementById('characterToggleBtn').classList.add('active'); }

    if(d.chocoCurlsPlacement){
        state.chocoCurlsPlacement = d.chocoCurlsPlacement;
        state.addons.set('Chocolate Curls', 0);
        const btn=document.querySelector('#opts-choco .addon-opt[data-val="Chocolate Curls"]'); if(btn) _setAddonOptChecked(btn,true);
        document.getElementById('chocoCurlsPlacementPanel').style.display='block';
        document.querySelectorAll('.choco-curls-place-btn').forEach(b=>{
            const on=b.dataset.placement===d.chocoCurlsPlacement;
            b.style.background=on?'var(--gold)':'var(--surface)'; b.style.color=on?'#fff':'var(--text-muted)'; b.style.fontWeight=on?'700':'600';
        });
    }
    if(d.plaqueShape){
        state.plaqueShape = d.plaqueShape; state.plaqueMessage = d.plaqueMessage || '';
        state.addons.set('Chocolate Plaque', 80);
        document.getElementById('plaqueToggleBtn').classList.add('active');
        document.getElementById('plaqueShapePanel').classList.add('visible');
        document.getElementById('opts-plaque-shape').querySelectorAll('[data-plaque-shape]').forEach(el=>el.classList.toggle('active', el.dataset.plaqueShape===d.plaqueShape));
        document.getElementById('plaqueShapeBadge').textContent = `Selected: ${d.plaqueShape} plaque`;
        document.getElementById('plaqueMessageInput').value = state.plaqueMessage;
    }
    if(d.sprinklePlacement && window._sprinklePlacement){
        Object.keys(d.sprinklePlacement).forEach(k=>{ window._sprinklePlacement[k] = d.sprinklePlacement[k]; });
    }
    (d.addons||[]).forEach(name=>{
        if(!state.addons.has(name)){
            const priceMap = {'Cylinder Sprinkles':30,'Sphere Sprinkles':30,'Chocolate Sprinkles':30,'Crushed Peanuts':35};
            state.addons.set(name, priceMap[name]||0);
            const el = document.querySelector(`[data-val="${CSS.escape(name)}"]`);
            if(el) el.classList.add('active');
        }
    });

    updateAll();

    // Wait for the cake model itself to finish loading before placing
    // decorations on it — placement raycasts need the mesh in the scene.
    await new Promise(res=>{
        const check=(n)=>{ if(typeof window.isCakeSceneReady==='function' && window.isCakeSceneReady()) res(); else if(n>0) setTimeout(()=>check(n-1),150); else res(); };
        check(40);
    });

    for(const f of (decor.fruits||[])){
        const idx = await window.placeFruitAtFraction(f.fruit, f.x, f.z, f.rotY);
        if(idx>=0 && f.rotZ!==undefined && typeof window.getFruitModels==='function'){
            const m = window.getFruitModels()[idx];
            if(m) m.group.rotation.z = f.rotZ*Math.PI/180;
        }
    }
    for(const p of (decor.ferrero||[])){
        const idx = await window.placeFerreroAtFraction(p.x, p.z);
        if(idx>=0 && typeof window.getFerreroModels==='function'){
            const m=window.getFerreroModels()[idx];
            if(m){ if(p.rotZ!==undefined) m.group.rotation.z=p.rotZ*Math.PI/180; if(p.rotY!==undefined) m.group.rotation.y=p.rotY*Math.PI/180; }
        }
    }
    for(const p of (decor.kitkat||[])) await window.placeKitkatAtFraction(p.x, p.z, p.orientation);
    for(const p of (decor.oreo||[]))   await window.placeOreoAtFraction(p.x, p.z, p.orientation);
    for(const p of (decor.barShard||[])){
        const idx = await window.placeBarShardAtFraction(p.x, p.z);
        if(idx>=0 && typeof window.getBarShardModels==='function'){
            const m=window.getBarShardModels()[idx];
            if(m){ if(p.rotZ!==undefined) m.group.rotation.z=p.rotZ*Math.PI/180; if(p.rotY!==undefined) m.group.rotation.y=p.rotY*Math.PI/180; }
        }
    }
    for(const p of (decor.toblerone||[])){
        const idx = await window.placeTobleroneAtFraction(p.x, p.z, p.flavor);
        if(idx>=0 && typeof window.getTobleroneModels==='function'){
            const m=window.getTobleroneModels()[idx];
            if(m){ if(p.rotZ!==undefined) m.group.rotation.z=p.rotZ*Math.PI/180; if(p.rotY!==undefined) m.group.rotation.y=p.rotY*Math.PI/180; }
        }
    }
    for(const p of (decor.candles||[])) await window.placeCandleAtFraction(p.num, p.x, p.z);
    for(const p of (decor.characters||[])){
        const idx = await window.placeCharacterAtFraction(p.key, p.x, p.z, p.size||4);
        if(idx>=0 && p.rotY!==undefined && typeof window.setCharacterYRotation==='function') window.setCharacterYRotation(idx, p.rotY);
    }
    if(decor.characters && decor.characters.length){
        const badge=document.getElementById('characterActiveBadge');
        if(badge) badge.textContent = `${decor.characters.length} placed — tap any character again to add more`;
    }
    if(state.allFruitsAssorted && typeof window.buildAllFruitsAssorted==='function'){
        await window.buildAllFruitsAssorted();
    } else {
        Object.keys(state.fruitGrams||{}).forEach(k=>{ if(typeof applyGramFruitVisual==='function') applyGramFruitVisual(k); });
    }
    if(typeof syncFruitGramUI==='function') syncFruitGramUI();
    if(d.chocoCurlsPlacement && typeof window.placeChocoCurls==='function'){
        window.placeChocoCurls(d.chocoCurlsPlacement, state.tier, state.shape, false);
    }
    if(d.plaqueShape && typeof window.placePlaqueOnCake==='function'){
        window.placePlaqueOnCake(d.plaqueShape).then(ok=>{ if(ok && state.plaqueMessage && typeof window.setPlaqueMessage==='function') window.setPlaqueMessage(state.plaqueMessage); });
    }
    if(state.addons.has('Cylinder Sprinkles') && typeof window.buildCylinderSprinkles==='function') window.buildCylinderSprinkles();
    if(state.addons.has('Sphere Sprinkles') && typeof window.buildPearlSprinkles==='function') window.buildPearlSprinkles();
    if(state.addons.has('Chocolate Sprinkles') && typeof window.buildChocoSprinkles==='function') window.buildChocoSprinkles();
    if(state.addons.has('Crushed Peanuts') && typeof window.buildCrushedPeanuts==='function') window.buildCrushedPeanuts();

    updateAll();
}

async function loadDraft(id){
    try{
        const d = await fetchDraftById(id);
        if(!d){showToast('No saved draft found');return;}
        await applyDraftConfig(d);
        showToast('✓ Draft loaded');
    }catch(e){console.error('[loadDraft]',e);showToast('⚠ Could not load draft');}
}

// ── Auto-resume a draft when arriving from the Saved Drafts page (?resume_draft=ID) ──
(function autoResumeDraft(){
    const params = new URLSearchParams(window.location.search);
    const resumeId = params.get('resume_draft');
    if(!resumeId) return;
    const tryResume=(attempts)=>{
        if(typeof window.updateModel==='function'){
            loadDraft(resumeId);
            window.history.replaceState({}, document.title, window.location.pathname);
        } else if(attempts>0){
            setTimeout(()=>tryResume(attempts-1),150);
        }
    };
    tryResume(30);
})();

// ── Interactive, read-only 3D viewer for the order tracker (?view_request=ID) ──
(function trackerViewer(){
    if(!new URLSearchParams(window.location.search).has('view_request')) return;
    let started = false;
    const post = (type, extra) => { try{ window.parent.postMessage(Object.assign({type}, extra||{}), window.location.origin); }catch(e){} };
    const LOG = (...a) => console.log('[BakeSphere 3D]', ...a);

    // ── Single combined-progress channel → Baker Order page + local overlay ──
    let _lastPct = -1;
    function sendTrackerProgress(percent){
        let p = Number(percent);
        if(!isFinite(p)) return;                        // never NaN / Infinity
        p = Math.max(0, Math.min(100, Math.round(p)));  // clamp 0..100
        if(p <= _lastPct) return;                       // never backward, no duplicate posts
        _lastPct = p;
        post('bakesphere-tracker-progress', { percent: p });
        const _tx = document.getElementById('loadingText'); if(_tx) _tx.textContent = 'Loading cake… ' + p + '%';
        LOG('Loading progress:', p + '%');
    }
    // Stages: default cake 5-30 → requested cake 30-75 (or 95 if no decorations)
    //         → decorations 75-97 → finalize 97 → 100 (only once truly ready).
    let phase = 'default';
    const RANGE = { default:[5,30], config:[30,95] };
    // Fed by _updateAggregateLoadProgress() with the REAL byte/file fraction of the current GLB batch.
    window._bsOnBatchProgress = function(fraction){
        const r = RANGE[phase]; if(!r) return;
        const f = Math.max(0, Math.min(1, Number(fraction) || 0));
        sendTrackerProgress(r[0] + (r[1]-r[0]) * f);
    };

    async function start(cfg){
        if(started || !cfg) return;
        started = true;
        LOG('Loading started');
        // wait for the default cake to finish, so decorations land on the real one
        for(let i=0;i<80;i++){
            if(typeof window.updateModel==='function' && typeof window.isCakeSceneReady==='function' && window.isCakeSceneReady() && !(window.isCakeBuilding && window.isCakeBuilding())) break;
            await new Promise(r=>setTimeout(r,150));
        }
        phase = 'config'; sendTrackerProgress(30);

        // Decoration stage: each placement counts as one unit, plus REAL byte progress
        // from any GLTFLoader.load() it triggers (patched only while the draft applies).
        const _decor = cfg.decorations || {};
        const decorTotal = ['fruits','ferrero','kitkat','oreo','barShard','toblerone','candles','characters']
            .reduce((n,k)=> n + (Array.isArray(_decor[k]) ? _decor[k].length : 0), 0);
        if(decorTotal > 0) RANGE.config[1] = 75;
        let decorDone = 0;
        const inflight = new Map();
        const decorProgress = ()=>{
            if(!decorTotal) return;
            let partial = 0; inflight.forEach(v=>{ partial += v; });
            sendTrackerProgress(75 + 22 * Math.min(1, (decorDone + partial) / decorTotal));
        };
        const restoreFns = [];
        ['placeFruitAtFraction','placeFerreroAtFraction','placeKitkatAtFraction','placeOreoAtFraction',
         'placeBarShardAtFraction','placeTobleroneAtFraction','placeCandleAtFraction','placeCharacterAtFraction']
            .forEach(name=>{
                const orig = window[name];
                if(typeof orig !== 'function') return;
                window[name] = async function(...args){
                    phase = 'decor'; decorProgress();
                    try{ return await orig.apply(this, args); }
                    finally{ decorDone++; decorProgress(); }
                };
                restoreFns.push(()=>{ window[name] = orig; });
            });
        const _GL = window._GLTFLoaderClass;   // exposed by the module script (classic scripts can't see its imports)
        const _origGLTFLoad = _GL && _GL.prototype.load;
        if(_origGLTFLoad) _GL.prototype.load = function(url, onLoad, onProgress, onError){
            const token = {};
            return _origGLTFLoad.call(this, url,
                g => { inflight.delete(token); if(onLoad) onLoad(g); },
                ev => {
                    if(phase === 'decor' && ev && ev.total > 0 && isFinite(ev.loaded / ev.total)){
                        inflight.set(token, Math.min(0.99, ev.loaded / ev.total)); decorProgress();
                    }
                    if(onProgress) onProgress(ev);
                },
                err => { inflight.delete(token); if(onError) onError(err); });
        };
        if(_origGLTFLoad) restoreFns.push(()=>{ _GL.prototype.load = _origGLTFLoad; });

        try{ await applyDraftConfig(cfg); }catch(err){ console.error('[TrackerViewer]', err); }
        finally{ restoreFns.forEach(fn=>{ try{ fn(); }catch(e){} }); }

        // Genuinely ready = cake meshes exist AND updateScene() has finished (isLoading false).
        for(let i=0;i<200;i++){
            if(typeof window.isCakeSceneReady==='function' && window.isCakeSceneReady() && !(window.isCakeBuilding && window.isCakeBuilding())) break;
            await new Promise(r=>setTimeout(r,100));
        }
        phase = 'final';
        LOG('All required assets loaded');
        sendTrackerProgress(97);

        // read-only: nothing can be picked up or moved, only rotate
        ['getFruitIndexAtScreen','getFerreroIndexAtScreen','getKitkatIndexAtScreen','getOreoIndexAtScreen',
         'getBarShardIndexAtScreen','getTobleroneIndexAtScreen','getCandleIndexAtScreen','getCharacterIndexAtScreen']
            .forEach(fn=>{ window[fn] = ()=>-1; });
        if(window._threeControls){
            // Disable zoom only when embedded inline in a scrollable page (the
            // customer's order tracker), where scroll-to-zoom would hijack the
            // page's own scroll. The baker's full-screen modal passes
            // allow_zoom=1 since there's no surrounding page to fight with.
            const allowZoom = new URLSearchParams(window.location.search).get('allow_zoom') === '1';
            window._threeControls.enableZoom = allowZoom;
            window._threeControls.enablePan  = false;
        }
        // Steeper, more top-down camera for the baker preview. Also applies to the
        // reset-view button, since it calls window.resetCamera() at click time.
        const TRACKER_ELEVATION_DEG = 40; // 0 = eye level, 90 = straight down
        if(typeof window.resetCamera==='function' && !window._bsTrackerCamPatched){
            window._bsTrackerCamPatched = true;
            const _origReset = window.resetCamera;
            window.resetCamera = function(){
                _origReset();
                const cam = window._threeCamera, ctl = window._threeControls;
                if(!cam || !ctl) return;
                const off = cam.position.clone().sub(ctl.target);
                const r = off.length();
                if(!(r > 0)) return;
                // Orbit/zoom around the cake's true center, so it sits mid-frame and
                // zooming in lands on the tiers instead of drifting above them.
                if(typeof window._getCakeBounds === 'function'){
                    const b = window._getCakeBounds();
                    if(b && isFinite(b.center.x + b.center.y + b.center.z)) ctl.target.copy(b.center);
                }
                const el = TRACKER_ELEVATION_DEG * Math.PI / 180;
                const az = Math.atan2(off.x, off.z); // keep the current left/right angle
                cam.position.set(
                    ctl.target.x + r * Math.cos(el) * Math.sin(az),
                    ctl.target.y + r * Math.sin(el),
                    ctl.target.z + r * Math.cos(el) * Math.cos(az)
                );
                ctl.update();
                if(typeof window._requestRender==='function') window._requestRender();
            };
        }
        if(typeof window.resetCamera==='function') window.resetCamera();
        setTimeout(()=>{
            sendTrackerProgress(100);
            LOG('Sending tracker-loaded');
            post('bakesphere-tracker-loaded');
        }, 900);
    }
    window.addEventListener('message', e=>{
        if(e.origin !== window.location.origin || e.source !== window.parent) return;
        if(e.data && e.data.type === 'bakesphere-tracker-config') start(e.data.config);
    });
    LOG('Tracker initialized');
    post('bakesphere-tracker-ready');
    sendTrackerProgress(5);
})();

// ── Read-only preview mode for the Saved Drafts gallery (?view_draft=ID) ──
// Rebuilds the full cake exactly as saved — shape, flavor, frosting, and
// every placed decoration — then hides all editing UI and locks the camera.
(function autoPreviewDraft(){
    const params = new URLSearchParams(window.location.search);
    const previewId = params.get('view_draft');
    if(!previewId) return;

    // IMPORTANT: Saved Drafts embeds this page as a transparent 3D viewer.
    // Do not use preview_image here. The draft config is rebuilt into the
    // same Three.js scene, including the base, frosting, rosettes, drips,
    // fruits, chocolates, candles, characters and other GLB decorations.
    const style = document.createElement('style');
    style.textContent = `
        html, body { width:100% !important; height:100% !important; margin:0 !important; overflow:hidden !important; background:transparent !important; }
        nav, .builder > .panel, .builder > .panel:last-child, .nav-center, .viewer-badge, .viewer-controls,
        #mobileSummaryBtn, #mobileSummarySheet, #tutorialOverlay, #toastContainer, .model-loading,
        .viewer > :not(#model-container):not(#fruitCanvas):not(.icing-anim-overlay) { display:none !important; }
        .builder { display:block !important; position:fixed !important; inset:0 !important; padding:0 !important; margin:0 !important; }
        .viewer { position:fixed !important; inset:0 !important; width:100% !important; height:100% !important; min-width:0 !important; }
        #model-container { position:absolute !important; inset:0 !important; width:100% !important; height:100% !important; background:transparent !important; }
        #model-container canvas { width:100% !important; height:100% !important; display:block !important; }
        #fruitCanvas { display:none !important; }
    `;
    document.head.appendChild(style);
    document.body.dataset.draftPreview = 'true';

    const tryPreview = async (attempts) => {
        if(typeof window.updateModel==='function'){
            try {
                const d = await fetchDraftById(previewId);
                if(!d) return;

                // Rebuild the actual 3D cake from the saved configuration.
                await applyDraftConfig(d);
                      if(window._threeControls){
                    window._threeControls.enabled = true;
                    const trayScale = parseFloat(new URLSearchParams(window.location.search).get('tray_scale')) || 1;
                    window._threeControls.rotateSpeed = 0.6 * trayScale;
                    window._threeControls.zoomSpeed = 0.8 * trayScale;
                }
                if(window._threeCamera && window._threeControls){
                    const tier = state ? state.tier : 'Single';
                    let camY = 1.6, camZ = 6.6, tgtY = -0.1;
                    if (tier === 'Two-tier')   { camY = 2.4; camZ = 7.8; tgtY = 0.2; }
                    if (tier === 'Three-tier') { camY = 3.4; camZ = 9.4; tgtY = 0.5; }
                    window._threeCamera.position.set(0, camY, camZ);
                    window._threeControls.target.set(0, tgtY, 0);
                    window._threeControls.update();
                }
                if(typeof window._requestRender === 'function') window._requestRender(1000);
                window.parent.postMessage({ type:'bakesphere-draft-3d-ready', draftId:previewId }, '*');
            } catch(e) {
                console.error('[SavedDraft 3D Preview]', e);
            }
        } else if(attempts>0){
            setTimeout(()=>tryPreview(attempts-1),150);
        }
    };
    tryPreview(40);
})();
// Full, baker-readable order config. Extends the old payload; nothing existing is removed.
function buildFullOrderConfig(){
    let cfg = {};
    try{ cfg = JSON.parse(document.getElementById('configInput').value || '{}'); }catch(e){}
    const NORMAL_H = 4; // inches tall at 100% height (same value the summary panel uses)
    const fr = state.frostings, on = k => state.addons.has(k);
    const fondant = fr.has('Fondant Smooth');
    const tc = tierCountFor(state.tier);
    const fmtIn = n => (Number.isInteger(n) ? n : n.toFixed(1)) + '"';
    const heightIn = Math.round(state.heightMult * NORMAL_H * 2) / 2;
    const join = a => a.filter(Boolean).join(' · ');
    const half = k => (state.halfView||{})[k] ? (state.halfView[k]==='left' ? 'left half only' : 'right half only') : '';
    const pct  = s => (s !== undefined && s < 0.99) ? Math.round(s*100) + '% size' : '';
    const tiersOf = k => {
        if(state.tier === 'Single') return '';
        const a = (state.tierDecor[k]||[]).filter(t => t < tc);
        return (a.length && a.length < tc) ? 'Tier ' + a.map(t => t+1).join(' & ') : '';
    };
    const models = fn => typeof window[fn]==='function' ? window[fn]() : [];
    const tally = (arr, f) => { const m={}; arr.forEach(x=>{ const k=f(x); m[k]=(m[k]||0)+1; });
        return Object.entries(m).map(([k,n])=>k+' ×'+n).join(', '); };
    const placed = arr => arr.length ? '×' + arr.length : 'not placed yet';

    const shapeText = state.shape==='Number' ? getShapeLabel() : getEffectiveShape();
    const resizable = ['Round','Square','Heart'].includes(state.shape) && state.tier==='Single';
    const style = fondant ? 'Fondant' : fr.has('Ombre Style') ? 'Ombre' : fr.has('Semi-naked Style') ? 'Semi-naked' : 'Buttercream';

    const cake = [['Type', state.cakeType], ['Shape', shapeText]];
    if(state.tier !== 'Single') cake.push(['Tiers', state.tier]);
    if(resizable){ cake.push(['Size', state.roundSize + '"']); cake.push(['Height', fmtIn(heightIn)]); }

    const flavor = [];
    for(let i=0;i<tc;i++){
        const L = state.shape==='Bundt' ? 1 : (state.tierLayers[i]||1), fi = state.tierFillings[i];
        flavor.push([tc>1 ? 'Tier '+(i+1)+(i===0?' (bottom)':i===tc-1?' (top)':'') : 'Cake',
            join([(state.tierFlavors[i]||state.flavor)+' cake',
                  L+(L>1?' layers':' layer'),
                  (L>1 && fi && fi!=='No Filling') ? fi+' filling' : '',
                  (state.tierFrostings[i]||state.flavor)+' frosting'])]);
    }

    const frost = [['Style', style]];
    if(fr.has('Ombre Style') && !fondant) frost.push(['Ombre colors', 'Top ' + state.ombreTopColor + ' → Bottom ' + state.ombreBottomColor]);
    if(!fondant){
        if(fr.has('Smooth Buttercream')) frost.push(['Shell border', join([state.shellBorderColorName, pct(state.shellBorderScale), half('shellBorder'), tiersOf('shell')])]);
        if(fr.has('Sugar Icing'))        frost.push(['Sugar icing',  join([state.icingColorName, pct(state.icingScale), half('sugarIcing'), tiersOf('icing')])]);
        if(fr.has('Rosettes')){
            const rp = state.rosettePlacement, hasB = rp.split('+').includes('Border');
            frost.push(['Rosettes', join([rp.replace('+',' + '), state.rosetteColorName,
                rp==='Border' ? pct(state.rosetteBorderScale) : '', rp==='Border' ? half('rosetteSides') : '', hasB ? tiersOf('rosette') : ''])]);
        }
        if(fr.has('Textured Buttercream')) frost.push(['Texture', 'Textured (colored per tier by its frosting flavor)']);
    }

    const deco = [];
    if(state.hasDrip) deco.push(['Drip', state.dripFlavor + ' drip']);
    if(state.allFruitsAssorted){
        deco.push(['Fruits', 'Assorted, full top']);
    } else {
        const piece = tally(models('getFruitModels'), m => m.fruit);
        if(piece) deco.push(['Fruits (by piece)', piece]);
        const HK = {'Mango Slice':'mangoBorder','Kiwi Slice':'kiwiBorder','Peach Slice':'peachBorder','Banana Slice':'bananaBorder'};
        GRAM_FRUIT_KEYS.forEach(k=>{
            if(!on(k)) return;
            let pl = (window._gramFruitPlacement||{})[k] || 'middle';
            if((state.shape==='Bundt'||state.shape==='Number') && pl==='middle') pl = 'border';
            if(state.tier!=='Single' && pl==='border') return; // listed per tier below
            const single = state.tier==='Single';
            deco.push([GRAM_FRUIT_LABELS[k]||k, join([(state.fruitGrams[k]||GRAM_DEFAULT)+'g',
                pl==='middle' ? 'center pile' : pl==='full' ? 'full top' : 'border',
                (pl==='border'&&single) ? pct(state.fruitBorderScale[k]) : '',
                (pl==='border'&&single) ? half(HK[k]) : ''])]);
        });
        if(state.tier!=='Single') for(let i=0;i<tc;i++){
            const f = state.tierFruitBorders[i];
            if(f && f!=='None') deco.push(['Tier '+(i+1)+' fruit border', GRAM_FRUIT_LABELS[f]||f]);
        }
    }
    if(on('Ferrero-style Ball'))  deco.push(['Ferrero', placed(models('getFerreroModels'))]);
    if(on('Kitkat Sticks'))       deco.push(['KitKat', join([placed(models('getKitkatModels')), state.kitkatOrientation==='standing'?'standing':'lying flat'])]);
    if(on('Oreo Cookie'))         deco.push(['Oreo', join([placed(models('getOreoModels')), state.oreoOrientation==='standing'?'standing':'lying flat'])]);
    if(on('Chocolate Bar Shard')) deco.push(['Bar shard', placed(models('getBarShardModels'))]);
    if(on('Toblerone Triangle'))  deco.push(['Toblerone', join([placed(models('getTobleroneModels')), state.tobleroneFlavor])]);
    if(on('Chocolate Curls')){
        const p = state.chocoCurlsPlacement, sides = p==='sides'||p==='both';
        deco.push(['Choco curls', join([p.charAt(0).toUpperCase()+p.slice(1), sides?pct(state.chocoCurlsSidesScale):'', sides?half('chocoCurlsSides'):''])]);
    }
    if(on('Chocolate Plaque')){
        const msg = (state.plaqueMessage||'').trim().replace(/\n+/g,' / ');
        deco.push(['Choco plaque', join([state.plaqueShape+' plaque', msg ? 'Message: “'+msg+'”' : 'no message'])]);
    }
    [['Cylinder Sprinkles','cylinder','Cylinder sprinkles'],['Sphere Sprinkles','pearl','Pearl sprinkles'],
     ['Chocolate Sprinkles','chocoSprinkle','Choco sprinkles'],['Crushed Peanuts','peanuts','Crushed peanuts']].forEach(([a,t,l])=>{
        if(!on(a)) return;
        const p = (window._sprinklePlacement||{})[t] || 'top';
        deco.push([l, p==='top' ? 'Top' : p==='sides' ? 'Sides' : 'Top & sides']);
    });
    if(on('Number Candles')){
        const nums = models('getCandleModels').map(m=>m.candleNum).sort((a,b)=>a-b);
        deco.push(['Number candles', nums.length ? nums.map(n=>'#'+n).join(', ') : 'not placed yet']);
    }
    if(on('Character Topper')){
        const ch = models('getCharacterModels');
        deco.push(['Character toppers', ch.length ? tally(ch, m=>m.key+' '+(m.sizeInches||4)+'"') : 'not placed yet']);
    }

    const num = id => parseInt((document.getElementById(id).textContent||'0').replace(/[^\d]/g,'')) || 0;
    const uniqueFlavors = [...new Set(state.tierFlavors.slice(0,tc))];
    const layersText = state.shape==='Bundt' ? '1' : state.tierLayers.slice(0,tc).join(' / ');
    const tags = [resizable ? state.roundSize+'" · '+fmtIn(heightIn)+' tall' : (state.tier!=='Single' ? state.tier : ''),
                  style,
                  (state.shape!=='Bundt' && state.tierLayers.slice(0,tc).some(n=>n>1)) ? 'Layers ' + layersText : ''].filter(Boolean);

    return Object.assign(cfg, {
        schema: 2,
        draft_config: buildDraftConfig(),
        cake_label: (uniqueFlavors.length>1 ? state.cakeType+' (mixed flavors)' : getCombinedCakeTypeLabel()) + ' · ' + shapeText,
        hero_tags: tags,
        size: resizable ? state.roundSize + '"' : '',
        layers: layersText,
        tier: state.tier,
        heightInches: resizable ? heightIn : null,
        tierFlavors: state.tierFlavors.slice(0,tc),
        tierFrostings: state.tierFrostings.slice(0,tc),
        tierFillings: state.tierFillings.slice(0,tc),
        tierLayers: state.tierLayers.slice(0,tc),
        baker_summary: [
            {title:'Cake', rows:cake}, {title:'Flavor & Layers', rows:flavor},
            {title:'Frosting', rows:frost}, {title:'Decorations', rows:deco}
        ].filter(g => g.rows.length),
        price_breakdown: { cake: num('priceBase'), frosting_extras: document.getElementById('priceFrostingRow').style.display==='none' ? 0 : num('priceFrosting'), addons: num('priceAddons') },
        total: num('priceTotal') || cfg.total   // the real on-screen total (old value skipped per-piece prices)
    });
}
function proceed(){
    const base=getBasePrice(),frostExtra=getFrostingExtraPrice();
    let addonTotal=0; state.addons.forEach(p=>addonTotal+=p);
    const isSugarIcing=state.frostings.has(SUGAR_ICING_VAL);
    const ferreroCount=(typeof window.getFerreroModels==='function')?window.getFerreroModels().length:0;
    const kitkatCount=(typeof window.getKitkatModels==='function')?window.getKitkatModels().length:0;
    const oreoCount=(typeof window.getOreoModels==='function')?window.getOreoModels().length:0;

document.getElementById('configInput').value=JSON.stringify({
        cakeType:state.cakeType,
        filling:state.filling,
        shape:state.shape,
        roundSize:state.shape==='Round'?state.roundSize:null,
        numberDigits:state.shape==='Number'?state.numberDigits:null,
        numberChoice:state.shape==='Number'&&state.numberDigits===1?state.numberChoice:null,
        numberTens:state.shape==='Number'&&state.numberDigits===2?state.numberTens:null,
        numberUnits:state.shape==='Number'&&state.numberDigits===2?state.numberUnits:null,
        shapeLabel:getShapeLabel(),
        flavor:state.flavor,
        frostings:[...state.frostings],
        frosting:[...state.frostings].join(' + '),
        hasDrip:state.hasDrip,
        dripFlavor:state.hasDrip?state.dripFlavor:null,
        hasIcing:isSugarIcing,
        icingColor:isSugarIcing?state.icingColor:null,
        icingColorName:isSugarIcing?state.icingColorName:null,
        addons:[...state.addons.keys()],
        ferreroCount,kitkatCount,kitkatOrientation:state.kitkatOrientation,
        oreoCount,oreoOrientation:state.oreoOrientation,
        placedFruits:state.placedFruits,
        placedFerrero:state.placedFerrero,
        placedKitkat:state.placedKitkat,
        placedOreo:state.placedOreo,
        total:base+frostExtra+addonTotal
    });

  // Capture canvas at beauty-shot angle then submit
    const canvas = document.querySelector('#model-container canvas');
  if (canvas &&
        window._threeCamera &&
        window._threeControls &&
        window._threeRenderer &&
        window._threeScene) {

        const _cam = window._threeCamera;
        const _ctl = window._threeControls;
        const _ren = window._threeRenderer;
        const _scn = window._threeScene;

        // Save current camera state
        const savedPos    = _cam.position.clone();
        const savedTarget = _ctl.target.clone();

// Move to a good front-facing angle
        const tier = state ? state.tier : 'Single';
        let camY = 0.8, camZ = 7.0, tgtY = -0.6;
        if (tier === 'Two-tier')   { camY = 1.2; camZ = 8.5; tgtY = -0.2; }
        if (tier === 'Three-tier') { camY = 1.8; camZ = 10.5; tgtY = 0.2; }

        _cam.position.set(0, camY, camZ);
        _ctl.target.set(0, tgtY, 0);
        _ctl.update();
        _ren.render(_scn, _cam);

        // Composite: warm background + WebGL canvas
        try {
            const off = document.createElement('canvas');
            off.width  = canvas.width;
            off.height = canvas.height;
            const ctx  = off.getContext('2d');
            const grad = ctx.createLinearGradient(0, 0, off.width, off.height);
            grad.addColorStop(0,   '#E8D5B0');
            grad.addColorStop(0.4, '#D9C49A');
            grad.addColorStop(0.7, '#C8AC7A');
            grad.addColorStop(1,   '#A07840');
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, off.width, off.height);
            ctx.drawImage(canvas, 0, 0);
            document.getElementById('cakePreviewInput').value =
                off.toDataURL('image/jpeg', 0.92);
        } catch(e) {
            console.warn('Canvas capture failed:', e);
        }

// Restore camera instantly
        _cam.position.copy(savedPos);
        _ctl.target.copy(savedTarget);
        _ctl.update();
    }

    try{ document.getElementById('configInput').value = JSON.stringify(buildFullOrderConfig()); }
    catch(err){ console.error('[buildFullOrderConfig]', err); } // falls back to the old payload
    document.getElementById('proceedForm').submit();
}
if(document.getElementById('btnProceed')) document.getElementById('btnProceed').addEventListener('click',proceed);
document.getElementById('btnProceedLg').addEventListener('click',proceed);
document.getElementById('btnResetView').addEventListener('click',()=>{if(typeof window.resetCamera==='function')window.resetCamera();showToast('View reset');});
let _sliceAnimFrame = null;
function animateSliceWedge(fromSpan, toSpan, duration, onDone){
    if(_sliceAnimFrame) cancelAnimationFrame(_sliceAnimFrame);
    if(!window.CakeSlice){ if(onDone) onDone(); return; }
    const rotationDeg = getEffectiveSliceRotation();
    const startTime = performance.now();
    const ctxBase = {
        flavor: getEffectiveInnerFlavorKey(),
        filling: state.tierFillings[0]||state.filling,
        rotationDeg, tier: state.tier,
        tierLayers: state.tierLayers, tierFlavors: state.tierFlavors, tierFillings: state.tierFillings,
    };
    let lastFaceRebuild = 0;
    // Rebuilding the cut-face mesh (raycasts + geometry) on every single
    // frame was the source of the lag. The wedge cutout itself (cheap plane
    // math) still updates every frame for a smooth sweep; the detailed cut
    // face just catches up periodically, then gets one final crisp rebuild.
    const FACE_REBUILD_INTERVAL = 90; // ms
    function frame(now){
        const t = Math.min(1, (now-startTime)/duration);
        const eased = t<0.5 ? 2*t*t : 1-Math.pow(-2*t+2,2)/2; // easeInOutQuad
        const currentSpan = fromSpan + (toSpan-fromSpan)*eased;
        const clampedSpan = Math.max(0.01, currentSpan);
        window.CakeSlice.updateClipOnly(rotationDeg, clampedSpan);
        if(now - lastFaceRebuild >= FACE_REBUILD_INTERVAL || t>=1){
            window.CakeSlice.update({...ctxBase, spanDeg: clampedSpan});
            lastFaceRebuild = now;
        }
        if(typeof window._requestRender==='function') window._requestRender(200);
        if(t<1){
            _sliceAnimFrame = requestAnimationFrame(frame);
        } else {
            _sliceAnimFrame = null;
            if(onDone) onDone();
        }
    }
    _sliceAnimFrame = requestAnimationFrame(frame);
}
document.getElementById('btnSliceOff').addEventListener('click',()=>{
    if(state.sliceEnabled === false) return;
    document.getElementById('btnSliceOff').classList.add('active');
    document.getElementById('btnSliceOn').classList.remove('active');
    showToast('Closing slice…',1200);
    // Sweep the wedge shut (40°→0°) so the cut visually "closes back up",
    // then fully disable clipping/cut-faces once it's flush again.
    animateSliceWedge(40, 0, 650, ()=>{
        state.sliceEnabled = false;
        if(window.CakeSlice) window.CakeSlice.disable();
        if(renderer) renderer.shadowMap.needsUpdate = true; // this direction never triggered a shadow refresh before
        showToast('Showing whole cake',1400);
    });
});
document.getElementById('btnSliceOn').addEventListener('click',()=>{
    if(state.sliceEnabled === true) return;
    state.sliceEnabled = true;
    document.getElementById('btnSliceOn').classList.add('active');
    document.getElementById('btnSliceOff').classList.remove('active');
    showToast('Slicing the cake…',1400);
    // Sweep the wedge open (0°→40°) so it reads as the slice being cut away.
    animateSliceWedge(0.01, 40, 750, ()=>{
        updateAll();
    });
});
if(typeof window._setSpotBrightness === 'function') window._setSpotBrightness(0.028);
window._updateAll=updateAll;
