function bindHalfViewButtons(containerId, key){
    const container = document.getElementById(containerId);
    if(!container) return;
    container.querySelectorAll('.half-view-btn').forEach(btn=>{
        btn.addEventListener('click', ()=>{
            const side = btn.dataset.halfSide || null;
            state.halfView[key] = side;
            container.querySelectorAll('.half-view-btn').forEach(b=>{
                const on = (b.dataset.halfSide||null) === side;
                b.style.background = on ? 'var(--caramel)' : 'var(--surface)';
                b.style.color = on ? '#fff' : 'var(--text-muted)';
            });
            if(typeof window._applyHalfViewFor === 'function') window._applyHalfViewFor(key);
        });
    });
}
function syncHalfViewButtonsUI(container, side){
    if(!container) return;
    container.querySelectorAll('.half-view-btn').forEach(b=>{
        const on = (b.dataset.halfSide||null) === side;
        b.style.background = on ? 'var(--caramel)' : 'var(--surface)';
        b.style.color = on ? '#fff' : 'var(--text-muted)';
    });
}
function bindHalfViewGroupFor(containerId, key, oppositeKey, oppositeContainerId){
    const container = document.getElementById(containerId);
    if(!container) return;
    container.querySelectorAll('.half-view-btn').forEach(btn=>{
        btn.addEventListener('click', ()=>{
            const side = btn.dataset.halfSide || null;
            state.halfView[key] = side;
            syncHalfViewButtonsUI(container, side);
            if(typeof window._applyHalfViewFor === 'function') window._applyHalfViewFor(key);
            // If the paired decoration is active on the SAME half, flip it to
            // the opposite half automatically so both stay visible.
            if(oppositeKey && side && state.halfView[oppositeKey] === side){
                const flip = side === 'left' ? 'right' : 'left';
                state.halfView[oppositeKey] = flip;
                syncHalfViewButtonsUI(document.getElementById(oppositeContainerId), flip);
                if(typeof window._applyHalfViewFor === 'function') window._applyHalfViewFor(oppositeKey);
                showToast('Adjusted the other side so both halves stay visible', 2000);
            }
        });
    });
}
function bindHalfViewGroupMulti(containerId, key, others){
    const container = document.getElementById(containerId);
    if(!container) return;
    container.querySelectorAll('.half-view-btn').forEach(btn=>{
        btn.addEventListener('click', ()=>{
            const side = btn.dataset.halfSide || null;
            state.halfView[key] = side;
            syncHalfViewButtonsUI(container, side);
            if(typeof window._applyHalfViewFor === 'function') window._applyHalfViewFor(key);
            if(side){
                others.forEach(o=>{
                    if(state.halfView[o.key] === side){
                        const flip = side === 'left' ? 'right' : 'left';
                        state.halfView[o.key] = flip;
                        syncHalfViewButtonsUI(document.getElementById(o.containerId), flip);
                        if(typeof window._applyHalfViewFor === 'function') window._applyHalfViewFor(o.key);
                        showToast('Adjusted the other side so both halves stay visible', 2000);
                    }
                });
            }
        });
    });
}
// ── Half Cake View: pairing rules ──
// When two of Shell Border / Sugar Icing / Rosette Border are combined:
//  • "Full" is disabled on BOTH (Full+Full, or Full+half, is never allowed
//    while paired — every combo must show two different, non-overlapping halves).
//  • Picking a side (left/right) on either one instantly flips the OTHER
//    paired one to the opposite side if it would otherwise overlap.
function oppositeHalf(side){ return side==='left' ? 'right' : side==='right' ? 'left' : null; }
function halfViewContainerId(key){
    if(key==='shellBorder')  return 'shellBorderHalfViewGroup';
    if(key==='sugarIcing')   return 'icingHalfViewGroup';
    if(key==='rosetteSides') return 'rosetteHalfViewGroup';
    return null;
}
function halfViewLabel(key){
    if(key==='shellBorder')  return 'Shell Border';
    if(key==='sugarIcing')   return 'Sugar Icing';
    if(key==='rosetteSides') return 'Rosette Border';
    return '';
}
function isHalfViewKeyActive(key){
    if(key==='shellBorder')  return state.frostings.has('Smooth Buttercream');
    if(key==='sugarIcing')   return state.frostings.has(SUGAR_ICING_VAL);
    if(key==='rosetteSides') return state.frostings.has('Rosettes') && state.rosettePlacement==='Border';
    return false;
}
// Finds whichever OTHER decoration is currently combined with `sourceKey`
// (each customer can only ever have 2 of these 3 active at once).
function getActiveComboPartner(sourceKey){
    const hasShell   = isHalfViewKeyActive('shellBorder');
    const hasSugar   = isHalfViewKeyActive('sugarIcing');
    const hasRosette = isHalfViewKeyActive('rosetteSides');

    if(sourceKey === 'shellBorder')  return hasRosette ? 'rosetteSides' : (hasSugar ? 'sugarIcing' : null);
    if(sourceKey === 'sugarIcing')   return hasRosette ? 'rosetteSides' : (hasShell ? 'shellBorder' : null);
    if(sourceKey === 'rosetteSides') return hasShell ? 'shellBorder' : (hasSugar ? 'sugarIcing' : null);
    return null;
}
function setHalfViewSide(key, side, containerId){
    state.halfView[key] = side;
    syncHalfViewButtonsUI(document.getElementById(containerId), side);
    if(typeof window._applyHalfViewFor === 'function') window._applyHalfViewFor(key);
}
// Enables/disables ONLY the "Full" button in a group — left/right stay clickable always.
function setFullButtonDisabled(key, disabled){
    const container = document.getElementById(halfViewContainerId(key));
    if(!container) return;
    const fullBtn = container.querySelector('.half-view-btn[data-half-side=""]');
    if(!fullBtn) return;
    fullBtn.disabled = disabled;
    fullBtn.style.opacity = disabled ? '0.35' : '';
    fullBtn.style.cursor = disabled ? 'not-allowed' : '';
    fullBtn.style.pointerEvents = disabled ? 'none' : '';
    fullBtn.title = disabled ? 'Not available while paired with another decoration' : '';
}
// Re-checks every possible pair and: (1) disables "Full" on both members of
// an active pair, (2) makes sure neither member is left sitting on "Full" —
// if one is, it's auto-assigned a side opposite its partner (or a sensible
// default of left/right if both are still unset).
function syncHalfViewLocks(){
    ['shellBorder','sugarIcing','rosetteSides'].forEach(k=>setFullButtonDisabled(k, false));
    [].forEach(([a,b])=>{ // pairing lock removed: rings now sit at different sizes
        if(!isHalfViewKeyActive(a) || !isHalfViewKeyActive(b)) return;
        setFullButtonDisabled(a, true);
        setFullButtonDisabled(b, true);
        const sideA = state.halfView[a], sideB = state.halfView[b];
        if(!sideA && !sideB){
            setHalfViewSide(a, 'left', halfViewContainerId(a));
            setHalfViewSide(b, 'right', halfViewContainerId(b));
        } else if(!sideA){
            setHalfViewSide(a, oppositeHalf(sideB), halfViewContainerId(a));
        } else if(!sideB){
            setHalfViewSide(b, oppositeHalf(sideA), halfViewContainerId(b));
        }
    });
}
// Called right when a decoration NEWLY joins an existing pairing (not via
// its own half-view button) — makes sure Full gets locked and both sides
// get assigned immediately instead of waiting for a manual click.
function applyComboHalfViewDefault(newKey){
    syncHalfViewLocks();
}
function bindComboHalfView(containerId, key){
    const container = document.getElementById(containerId);
    if(!container) return;
    container.querySelectorAll('.half-view-btn').forEach(btn=>{
        btn.addEventListener('click', ()=>{
            if(btn.disabled) return;
            const side = btn.dataset.halfSide || null;
            setHalfViewSide(key, side, containerId);
            const partnerKey = null; // no auto-split anymore
            if(partnerKey && side && state.halfView[partnerKey] === side){
                setHalfViewSide(partnerKey, oppositeHalf(side), halfViewContainerId(partnerKey));
                showToast(halfViewLabel(partnerKey)+' switched to the opposite half so they don\'t overlap', 2000);
            }
            syncHalfViewLocks();
        });
    });
}
bindComboHalfView('icingHalfViewGroup', 'sugarIcing');
bindComboHalfView('shellBorderHalfViewGroup', 'shellBorder');
bindComboHalfView('rosetteHalfViewGroup', 'rosetteSides');
bindHalfViewButtons('chocoCurlsHalfViewGroup', 'chocoCurlsSides');
const FRUIT_HALF_KEY_MAP = {'Mango Slice':'mangoBorder','Kiwi Slice':'kiwiBorder','Peach Slice':'peachBorder','Banana Slice':'bananaBorder'};
document.querySelectorAll('.fruit-half-view-group').forEach(group=>{
    const key = FRUIT_HALF_KEY_MAP[group.dataset.fruitKey];
    group.querySelectorAll('.half-view-btn').forEach(btn=>{
        btn.addEventListener('click', ()=>{
            const side = btn.dataset.halfSide || null;
            state.halfView[key] = side;
            group.querySelectorAll('.half-view-btn').forEach(b=>{
                const on = (b.dataset.halfSide||null) === side;
                b.style.background = on ? 'var(--caramel)' : 'var(--surface)';
                b.style.color = on ? '#fff' : 'var(--text-muted)';
            });
            if(typeof window._applyHalfViewFor === 'function') window._applyHalfViewFor(key);
        });
    });
});

(function applyPreset() {
    const params = new URLSearchParams(window.location.search);
    if (!params.has('preset_flavor')) return;

    const flavor     = params.get('preset_flavor');
    const shape      = params.get('preset_shape')       || 'Round';
    const size       = parseInt(params.get('preset_size') || '6');
    const frosting   = params.get('preset_frosting')    || 'Smooth Buttercream';
    const hasDrip    = params.get('preset_drip')        === '1';
    const dripFlavor = params.get('preset_drip_flavor') || 'Vanilla';
    const sprinkles  = params.get('preset_addon_sprinkles') || null;
    const presetName = params.get('preset_name')        || null;

    // Shape
    state.shape = shape;
    state.roundSize = size;
    document.getElementById('opts-shape').querySelectorAll('[data-val]').forEach(el => {
        el.classList.toggle('active', el.dataset.val === shape);
    });
    document.getElementById('sizeRange').value = size;
    document.getElementById('sizeDisplay').textContent = size;
    syncSizeSliderVisibility();
    document.getElementById('numberPickerWrap').classList.toggle('visible', shape === 'Number');

    // Number cake digits (only relevant when shape === 'Number')
    if (shape === 'Number') {
        const numDigits = parseInt(params.get('preset_number_digits') || '1');
        state.numberDigits = numDigits;
        if (numDigits === 2) {
            state.numberTens  = parseInt(params.get('preset_number_tens')  || '1');
            state.numberUnits = parseInt(params.get('preset_number_units') || '0');
            document.getElementById('btnDualDigit').classList.add('active');
            document.getElementById('btnSingleDigit').classList.remove('active');
            document.getElementById('singleDigitSection').style.display = 'none';
            document.getElementById('dualDigitSection').classList.add('visible');
            document.getElementById('opts-tens').querySelectorAll('.num-opt-sm').forEach(el => {
                el.classList.toggle('active', parseInt(el.dataset.val) === state.numberTens);
            });
            document.getElementById('opts-units').querySelectorAll('.num-opt-sm').forEach(el => {
                el.classList.toggle('active', parseInt(el.dataset.val) === state.numberUnits);
            });
            refreshDualPreview();
        } else {
            state.numberChoice = parseInt(params.get('preset_number_choice') || '0');
            document.getElementById('opts-number').querySelectorAll('.num-opt').forEach(el => {
                el.classList.toggle('active', parseInt(el.dataset.val) === state.numberChoice);
            });
        }
    }

    // Flavor
    state.flavor = flavor;
    state.tierFlavors[0] = flavor;
    state.tierFrostings[0] = flavor;
    // Frosting
    state.frostings = new Set();
     const CAKE_STYLE_MAP = {
        'Smooth Buttercream':   () => { state.frostings.add('Smooth Buttercream'); },
        'Semi-naked Style':     () => { state.frostings.add('Semi-naked Style'); },
        'Fondant Smooth':       () => { state.frostings.add('Fondant Smooth'); },
        'Sugar Icing':          () => { state.frostings.add('Sugar Icing'); },
        'Textured Buttercream': () => {
            state.frostings.add('Smooth Buttercream');
            state.frostings.add('Textured Buttercream');
        },
        'Rosettes': () => { state.frostings.add('Semi-naked Style'); state.frostings.add('Rosettes'); },
    };
    (CAKE_STYLE_MAP[frosting] || CAKE_STYLE_MAP['Smooth Buttercream'])();

    // Rosette placement + color (only meaningful when frosting === 'Rosettes')
    const presetRosettePlacement = params.get('preset_rosette_placement');
    const presetRosetteColor     = params.get('preset_rosette_color');
    const presetRosetteColorName = params.get('preset_rosette_color_name');
    if (frosting === 'Rosettes' && presetRosettePlacement) {
        state.rosettePlacement = presetRosettePlacement;
        if (presetRosetteColor) {
            state.rosetteColor = presetRosetteColor;
            state.rosetteColorName = presetRosetteColorName || presetRosetteColor;
        }
    }

    // Base icing color (Shell Border / Sugar Icing)
    const presetIcingColor     = params.get('preset_icing_color');
    const presetIcingColorName = params.get('preset_icing_color_name');
    if (presetIcingColor) {
        state.icingColor = presetIcingColor;
        state.icingColorName = presetIcingColorName || presetIcingColor;
        state.hasCustomIcingColor = true;
        document.getElementById('icingColorGrid').querySelectorAll('.icing-color-opt').forEach(el => {
            el.classList.toggle('active', el.dataset.icingColor === presetIcingColor);
        });
        document.getElementById('icingColorLabel').textContent = state.icingColorName;
    }

    syncFrostingUI();

    // Rosette UI sync (placement buttons + color swatches)
    if (frosting === 'Rosettes') {
        document.querySelectorAll('#opts-rosette-placement [data-rosette-placement], #opts-rosette-combo [data-rosette-placement]').forEach(el => {
            el.classList.toggle('active', el.dataset.rosettePlacement === state.rosettePlacement);
        });
        const badge = document.getElementById('rosettePlacementBadge');
        if (badge) badge.textContent = 'Selected: ' + state.rosettePlacement.replace('+',' + ');
        document.getElementById('rosetteColorGrid').querySelectorAll('.icing-color-opt').forEach(el => {
            el.classList.toggle('active', el.dataset.rosetteColor === state.rosetteColor);
        });
        document.getElementById('rosetteColorLabel').textContent = state.rosetteColorName;
        window._pendingRosetteReveal = true;
    }
    // Drip
    if (hasDrip) {
        state.hasDrip = true;
        state.dripFlavor = dripFlavor;
        state.addons.set('Drip', 180);
        document.getElementById('dripToggleBtn').classList.add('active');
        document.getElementById('dripFlavorPanel').classList.add('visible');
        document.getElementById('dripFlavorOpts').querySelectorAll('.drip-flavor-opt').forEach(el => {
            el.classList.toggle('active', el.dataset.dripFlavor === dripFlavor);
        });
    }
    // Choco Curls (optional add-on placement — 'middle' | 'sides' | 'both')
    const presetChocoCurls = params.get('preset_choco_curls');
    if (presetChocoCurls) {
        state.chocoCurlsPlacement = presetChocoCurls;
        state.addons.set('Chocolate Curls', ADDON_TIER_PRICES['Chocolate Curls'][getTierIdx()]);
        const chocoCurlsBtn = document.querySelector('#opts-choco .addon-opt[data-val="Chocolate Curls"]');
        if (chocoCurlsBtn) _setAddonOptChecked(chocoCurlsBtn, true);
        document.getElementById('chocoCurlsPlacementPanel').style.display = 'block';
        document.querySelectorAll('.choco-curls-place-btn').forEach(b => {
            const on = b.dataset.placement === presetChocoCurls;
            b.style.background = on ? 'var(--gold)' : 'var(--surface)';
            b.style.color      = on ? '#fff'         : 'var(--text-muted)';
            b.style.fontWeight = on ? '700'          : '600';
        });
        setTimeout(() => _tryPlaceChocoCurls(presetChocoCurls, 25), 1000);
    }

    // Sprinkles
    if (sprinkles) {
        const sprinkleEl = document.querySelector(`#opts-sprinkles .addon-opt[data-val="${sprinkles}"]`);
        if (sprinkleEl) {
            state.addons.set(sprinkles, parseInt(sprinkleEl.dataset.price) || 30);
            sprinkleEl.classList.add('active');
            const _waitAndBuild = (attempts) => {
                if (typeof window.buildCylinderSprinkles === 'function') {
                    if (sprinkles === 'Cylinder Sprinkles') {
                        window.buildCylinderSprinkles();
                        document.getElementById('cylinderPlacementPanel').style.display = 'block';
                    }
                    if (sprinkles === 'Sphere Sprinkles') {
                        window.buildPearlSprinkles();
                        document.getElementById('pearlPlacementPanel').style.display = 'block';
                    }
                } else if (attempts > 0) {
                    setTimeout(() => _waitAndBuild(attempts - 1), 300);
                }
            };
            setTimeout(() => _waitAndBuild(15), 800);
        }
    }
       // Fruits — auto-place fruit once the cake model is ready.
    //  • preset_fruit_positions="x:z,x:z,..." → EXACT spots. Each x/z is a
    //    fraction of the cake's radius from its center (0 = center,
    //    roughly -1..1 = edge). x>0=right, x<0=left, z>0=front, z<0=back.
    //    One fruit is placed per pair, and this takes priority over count.
    //  • preset_fruit_count="N" → fallback auto-cluster near center (old behavior).
    const presetFruit          = params.get('preset_fruit');
    const presetFruitCount     = parseInt(params.get('preset_fruit_count') || '0');
    const presetFruitPositions = params.get('preset_fruit_positions');

    if (presetFruit && (presetFruitCount > 0 || presetFruitPositions)) {
        const fruitBtn = document.querySelector(`#opts-fruits .addon-opt[data-val="${presetFruit}"]`);
        if (fruitBtn) {
            state.addons.set(presetFruit, 0);
            fruitBtn.classList.add('active');
            updateFruitTray();
        }

        if (presetFruitPositions) {
            // ── EXACT COORDINATES MODE ──
            const coords = presetFruitPositions.split(',').map(pair => {
                const [x, z] = pair.split(':').map(Number);
                return { x, z };
            }).filter(p => isFinite(p.x) && isFinite(p.z));

            const waitThenPlace = (attempts) => {
                if (typeof window.placeFruitAtFraction === 'function' && typeof window.isCakeSceneReady === 'function' && window.isCakeSceneReady()) {
                    let i = 0;
                    const placeOne = (retriesLeft) => {
                        if (i >= coords.length) { updateAll(); return; }
                        const { x, z } = coords[i];
                        window.placeFruitAtFraction(presetFruit, x, z).then(idx => {
                            if (idx < 0 && retriesLeft > 0) {
                                setTimeout(() => placeOne(retriesLeft - 1), 250);
                                return;
                            }
                            if (idx >= 0) window._placedFruitRecord[idx] = { fruit: presetFruit, emoji: '' };
                            i++;
                            placeOne(3);
                        });
                    };
                    placeOne(3);
                } else if (attempts > 0) {
                    setTimeout(() => waitThenPlace(attempts - 1), 300);
                }
            };
            setTimeout(() => waitThenPlace(20), 1000);
        } else {
            // ── AUTO-CLUSTER MODE (fallback) ──
            const dropAtCakeCenter = (attempts) => {
                if (typeof window.placeFruitOnCake === 'function' && typeof window.isCakeSceneReady === 'function' && window.isCakeSceneReady()) {
                    const viewerRect = document.getElementById('viewerEl').getBoundingClientRect();
                    const cx = viewerRect.left + viewerRect.width / 2;
                    const cy = viewerRect.top + viewerRect.height / 2;
                    let placed = 0;
                    const GOLDEN_ANGLE = 137.508 * Math.PI / 180;
                    const placeOne = (retriesLeft) => {
                        const angle = placed * GOLDEN_ANGLE;
                        const radius = 5 + placed * 4;
                        const px = cx + Math.cos(angle) * radius;
                        const py = cy + Math.sin(angle) * radius;
                        window.placeFruitOnCake(presetFruit, px, py).then(idx => {
                            if (idx < 0 && retriesLeft > 0) {
                                setTimeout(() => placeOne(retriesLeft - 1), 250);
                                return;
                            }
                            if (idx >= 0) window._placedFruitRecord[idx] = { fruit: presetFruit, emoji: '' };
                            placed++;
                            if (placed < presetFruitCount) placeOne(3);
                            else updateAll();
                        });
                    };
                    placeOne(3);
                } else if (attempts > 0) {
                    setTimeout(() => dropAtCakeCenter(attempts - 1), 300);
                }
            };
            setTimeout(() => dropAtCakeCenter(20), 1000);
        }
    }
    // Character toppers — place one or more named characters at exact
    // coordinates. preset_characters is a comma-separated list of character
    // keys (matching CHARACTER_FILE_MAP), preset_character_positions is a
    // matching comma-separated list of "x:z" fraction pairs.
    const presetCharacters         = params.get('preset_characters');
    const presetCharacterPositions = params.get('preset_character_positions');
    if (presetCharacters && presetCharacterPositions) {
        const charKeys = presetCharacters.split(',').map(s => s.trim());
        const coords = presetCharacterPositions.split(',').map(pair => {
            const [x, z] = pair.split(':').map(Number);
            return { x, z };
        });

        if (!state.addons.has('Character Topper')) {
            state.addons.set('Character Topper', 0);
            document.getElementById('characterToggleBtn').classList.add('active');
            document.getElementById('characterPickerPanel').classList.add('visible');
        }

        const waitThenPlaceChars = (attempts) => {
            if (typeof window.placeCharacterAtFraction === 'function' && typeof window.isCakeSceneReady === 'function' && window.isCakeSceneReady()) {
                let i = 0;
                const placeOne = (retriesLeft) => {
                    if (i >= charKeys.length) { updateAll(); return; }
                    const key = charKeys[i];
                    const pos = coords[i] || { x: 0, z: 0 };
                    window.placeCharacterAtFraction(key, pos.x, pos.z).then(idx => {
                        if (idx < 0 && retriesLeft > 0) {
                            setTimeout(() => placeOne(retriesLeft - 1), 250);
                            return;
                        }
                        i++;
                        placeOne(3);
                    });
                };
                placeOne(3);
            } else if (attempts > 0) {
                setTimeout(() => waitThenPlaceChars(attempts - 1), 300);
            }
        };
        setTimeout(() => waitThenPlaceChars(20), 1200);
    }

    // Number candles — place specific candle numbers at exact coordinates.
    const presetCandleNumbers   = params.get('preset_candle_numbers');
    const presetCandlePositions = params.get('preset_candle_positions');
    if (presetCandleNumbers && presetCandlePositions) {
        const nums = presetCandleNumbers.split(',').map(s => parseInt(s.trim()));
        const coords = presetCandlePositions.split(',').map(pair => {
            const [x, z] = pair.split(':').map(Number);
            return { x, z };
        });

        if (!state.addons.has('Number Candles')) {
            state.addons.set('Number Candles', 0);
            document.getElementById('opts-candles').querySelector('[data-val="Number Candles"]').classList.add('active');
            document.getElementById('candlePickerPanel').classList.add('visible');
        }

        const waitThenPlaceCandles = (attempts) => {
            if (typeof window.placeCandleAtFraction === 'function' && typeof window.isCakeSceneReady === 'function' && window.isCakeSceneReady()) {
                let i = 0;
                const placeOne = (retriesLeft) => {
                    if (i >= nums.length) { updateCandleTray(); updateAll(); return; }
                    const num = nums[i];
                    const pos = coords[i] || { x: 0, z: 0 };
                    window.placeCandleAtFraction(num, pos.x, pos.z).then(idx => {
                        if (idx < 0 && retriesLeft > 0) {
                            setTimeout(() => placeOne(retriesLeft - 1), 250);
                            return;
                        }
                        if (idx >= 0) window._placedCandleRecord[idx] = { num };
                        i++;
                        placeOne(3);
                    });
                };
                placeOne(3);
            } else if (attempts > 0) {
                setTimeout(() => waitThenPlaceCandles(attempts - 1), 300);
            }
        };
        setTimeout(() => waitThenPlaceCandles(20), 1300);
    }

    // Toast
    if (presetName) {
        setTimeout(() => showToast(`✨ "${presetName}" loaded — customize it your way!`, 3200), 1200);
    }

    // Clean URL
    window.history.replaceState({}, document.title, window.location.pathname);
})();
function tryInit(){if(typeof window.updateModel==='function')updateAll();else setTimeout(tryInit,80);}
tryInit();
// Skip speculative cache-warming in tracker mode — it exists to make live
// editing snappy in the interactive builder, and only competes for
// bandwidth/CPU here, slowing down the one cake actually being shown.
if(!document.body.classList.contains('tracker-mode')){
    setTimeout(()=>{ if(typeof window._prefetchRosetteModels==='function') window._prefetchRosetteModels(state.shape); }, 400);
    setTimeout(()=>{ if(typeof window._preloadAllDecorationAssets==='function') window._preloadAllDecorationAssets(); }, 4000);
}


// ── MOBILE SUMMARY SHEET ──
function initMobileSummary(){
    const btn     = document.getElementById('mobileSummaryBtn');
    const sheet   = document.getElementById('mobileSummarySheet');
    const close   = document.getElementById('closeMobileSummary');
    const content = document.getElementById('mobileSummaryContent');
    const badge   = document.getElementById('mobileTotalBadge');

    if(!btn || !sheet || !close || !content || !badge) return; // guard

    function isMobile(){ return window.innerWidth <= 768; }

    function updateMobileBtn(){
        btn.style.display = isMobile() ? 'flex' : 'none';
        badge.textContent = '₱' + document.getElementById('priceTotal').textContent;
    }

    function showSheet(){
        const rightPanel = document.querySelector('.panel:last-child');
        content.innerHTML = rightPanel ? rightPanel.innerHTML : '';
        sheet.style.display = 'block';
        document.body.style.overflow = 'hidden';
    }

    function hideSheet(){
        sheet.style.display = 'none';
        document.body.style.overflow = '';
    }

    btn.addEventListener('click', showSheet);
    close.addEventListener('click', hideSheet);
    sheet.addEventListener('click', e => { if(e.target === sheet) hideSheet(); });
    window.addEventListener('resize', updateMobileBtn);
    updateMobileBtn();

    // Keep badge synced with total
    const totalEl = document.getElementById('priceTotal');
    if(totalEl){
        new MutationObserver(()=>{
            badge.textContent = '₱' + totalEl.textContent;
        }).observe(totalEl, {childList:true, characterData:true, subtree:true});
    }
}
initMobileSummary();
</script>
